def _extraer_proveedor_telegram(texto):
    t = _telegram_texto_norm(texto)
    for pref in ("que trajo ", "que compro ", "que ingreso ", "trajo ", "compras de ", "proveedor "):
        if pref in t:
            val = t.split(pref, 1)[1]
            val = re.split(r"\b(hoy|ayer|esta semana|semana pasada|mes|julio|junio|mayo|abril)\b", val, 1)[0]
            val = re.sub(r"[^a-z0-9 ]+", " ", val).strip()
            if val:
                return val
    return None


def _rango_desde_texto_telegram(texto):
    t = _telegram_texto_norm(texto)
    hoy = date.today()
    if "ayer" in t:
        d = hoy - timedelta(days=1)
        return d.strftime("%Y-%m-%d"), hoy.strftime("%Y-%m-%d"), "ayer"
    if "semana" in t or "ultimos 7" in t:
        fin = hoy + timedelta(days=1)
        inicio = fin - timedelta(days=7)
        return inicio.strftime("%Y-%m-%d"), fin.strftime("%Y-%m-%d"), "ultimos 7 dias"
    if "hoy" in t:
        return hoy.strftime("%Y-%m-%d"), (hoy + timedelta(days=1)).strftime("%Y-%m-%d"), "hoy"
    periodo = _periodo_desde_texto(texto)
    inicio, fin = _rango_periodo(periodo)
    return inicio, fin, periodo


def responder_telegram_materiales_proveedor(texto):
    prov = _extraer_proveedor_telegram(texto)
    if not prov:
        return None
    inicio, fin, etiqueta = _rango_desde_texto_telegram(texto)
    where = _sql_tipo_compra_proveedor() + " AND UPPER(Proveedor) LIKE %s"
    like = "%" + prov.upper().replace(" ", "%") + "%"
    data = _telegram_sql_top_rango(where, (like,), dim="__material__", inicio=inicio, fin=fin, limite=10)
    tot = _telegram_total_rango(where, (like,), inicio=inicio, fin=fin)
    total = (tot.get("row") or {}).get("kg") if tot.get("ok") else None
    if data.get("ok") and not data.get("rows"):
        return f"No veo compra real de '{prov}' en {etiqueta}."
    return _respuesta_top_telegram(f"Materiales de {prov} ({etiqueta}, compra real)", "Total", data, total)


def responder_telegram_resumen_semana(texto):
    t = _telegram_texto_norm(texto)
    if "semana" not in t and "ultimos 7" not in t:
        return None
    inicio, fin, etiqueta = _rango_desde_texto_telegram(texto)
    prod = _telegram_sql_top_rango("UPPER(TRIM(TiposDeMovimiento)) = 'PRODUCCION'", dim="Maquina", inicio=inicio, fin=fin, limite=5)
    prod_tot = _telegram_total_rango("UPPER(TRIM(TiposDeMovimiento)) = 'PRODUCCION'", inicio=inicio, fin=fin)
    ing = _telegram_sql_top_rango(_sql_tipo_compra_proveedor(), dim="Proveedor", inicio=inicio, fin=fin, limite=5)
    ing_tot = _telegram_total_rango(_sql_tipo_compra_proveedor(), inicio=inicio, fin=fin)
    mov = _telegram_sql_top_rango("1=1", dim="TiposDeMovimiento", inicio=inicio, fin=fin, limite=6)
    lineas = [f"Resumen de planta ({etiqueta}):", ""]
    lineas.append(f"Produccion total: {_fmt_kg_telegram((prod_tot.get('row') or {}).get('kg') if prod_tot.get('ok') else 0)}.")
    for r in (prod.get("rows") or [])[:5]:
        lineas.append(f"- {r.get('nombre')}: {_fmt_kg_telegram(r.get('kg'))}")
    lineas.append("")
    lineas.append(f"Compra real registrada: {_fmt_kg_telegram((ing_tot.get('row') or {}).get('kg') if ing_tot.get('ok') else 0)}.")
    for r in (ing.get("rows") or [])[:5]:
        lineas.append(f"- {r.get('nombre')}: {_fmt_kg_telegram(r.get('kg'))}")
    lineas.append("")
    lineas.append("Movimientos principales:")
    for r in (mov.get("rows") or [])[:6]:
        lineas.append(f"- {r.get('nombre')}: {_fmt_kg_telegram(r.get('kg'))} ({int(r.get('registros') or 0)} registros)")
    return "\n".join(lineas)
def _telegram_total(where, args=(), periodo=None, hoy=False):
    conn = get_db_connection()
    if not conn:
        return {"ok": False, "error": "sin_conexion_db"}
    try:
        cur = conn.cursor()
        if hoy:
            rango_sql = "FechaHora >= CURDATE() AND FechaHora < CURDATE() + INTERVAL 1 DAY"
            params = tuple(args)
        else:
            inicio, fin = _rango_periodo(periodo or date.today().strftime("%Y-%m"))
            rango_sql = "FechaHora >= %s AND FechaHora < %s"
            params = (inicio, fin) + tuple(args)
        cur.execute(f"SELECT COUNT(*) AS registros, ROUND(COALESCE(SUM(kilos),0),1) AS kg FROM TiposDeMovimiento WHERE {rango_sql} AND {where}", params)
        row = cur.fetchone() or {}
        cur.close(); conn.close()
        return {"ok": True, "row": row}
    except Exception as e:
        try:
            conn.close()
        except Exception:
            pass
        return {"ok": False, "error": str(e)}


def _fmt_kg_telegram(v):
    return formatear_numero_telegram(float(v or 0), "kg")


def _respuesta_top_telegram(titulo, total_label, data, total=None):
    if not data.get("ok"):
        return f"No pude consultar la base local ({data.get('error')})."
    rows = data.get("rows") or []
    if not rows:
        return f"{titulo}: sin registros."
    lineas = [titulo + ":"]
    for r in rows[:10]:
        lineas.append(f"- {r.get('nombre')}: {_fmt_kg_telegram(r.get('kg'))} ({int(r.get('registros') or 0)} registros)")
    if total is not None:
        lineas.append("")
        lineas.append(f"{total_label}: {_fmt_kg_telegram(total)}.")
    return "\n".join(lineas)


def responder_telegram_deterministico(texto):
    t = _telegram_texto_norm(texto)
    periodo = _periodo_desde_texto(texto)
    es_hoy = "hoy" in t or "vinieron" in t

    if t in ("hola", "buenas", "ola") or t.startswith("hola "):
        return ("Hola. Estoy escuchando desde la mini PC.\n"
                "Puedo responder liviano: proveedores hoy, compras del mes, produccion hoy/mes, despachos hoy/mes, estado.")

    if "estado" in t or "status" in t:
        return (f"Servidor activo. Telegram inbox: {'on' if TELEGRAM_INBOX_ENABLED else 'off'}. "
                f"MQTT: {'conectado' if MQTT_STATUS.get('connected') else 'sin conexion'} ({MQTT_STATUS.get('last_error') or 'sin error reciente'}).")

    resp_semana = responder_telegram_resumen_semana(texto)
    if resp_semana:
        return resp_semana

    resp_materiales = responder_telegram_materiales_proveedor(texto)
    if resp_materiales:
        return resp_materiales

    if ("proveedor" in t or "proveedores" in t or "compra" in t or "compras" in t or "ingreso" in t or "ingresos" in t) and ("hoy" in t or "vinieron" in t):
        where = _sql_tipo_compra_proveedor()
        data = _telegram_sql_top(where, dim="Proveedor", hoy=True, limite=10)
        total = sum(float(r.get("kg") or 0) for r in (data.get("rows") or [])) if data.get("ok") else None
        return _respuesta_top_telegram("Proveedores con compra real registrada hoy", "Total compra real hoy", data, total)

    if "compra" in t or "compras" in t or "proveedor" in t or "proveedores" in t:
        where = _sql_tipo_compra_proveedor()
        data = _telegram_sql_top(where, dim="Proveedor", periodo=periodo, limite=10)
        tot = _telegram_total(where, periodo=periodo)
        total = (tot.get("row") or {}).get("kg") if tot.get("ok") else None
        return _respuesta_top_telegram(f"Top proveedores de compra real {periodo}", "Total compra real", data, total)

    if "produccion" in t or "produjeron" in t or "maquina" in t or "maquinas" in t:
        where = "UPPER(TRIM(TiposDeMovimiento)) = 'PRODUCCION'"
        dim = "Maquina" if "maquina" in t or "maquinas" in t else "Operador"
        data = _telegram_sql_top(where, dim=dim, hoy=es_hoy, periodo=periodo, limite=10)
        tot = _telegram_total(where, hoy=es_hoy, periodo=periodo)
        total = (tot.get("row") or {}).get("kg") if tot.get("ok") else None
        alcance = "hoy" if es_hoy else periodo
        return _respuesta_top_telegram(f"Produccion por {dim.lower()} {alcance}", "Total produccion", data, total)

    if "despacho" in t or "despachos" in t or "venta" in t or "ventas" in t or "cliente" in t or "clientes" in t:
        where = "UPPER(TRIM(TiposDeMovimiento)) LIKE %s AND UPPER(TiposDeMovimiento) NOT LIKE %s"
        args = ("DESPACHO%", "%DEVOLUCION%")
        data = _telegram_sql_top(where, args=args, dim="Proveedor", hoy=es_hoy, periodo=periodo, limite=10)
        tot = _telegram_total(where, args=args, hoy=es_hoy, periodo=periodo)
        total = (tot.get("row") or {}).get("kg") if tot.get("ok") else None
        alcance = "hoy" if es_hoy else periodo
        return _respuesta_top_telegram(f"Despachos por cliente/destino {alcance}", "Total despachado", data, total)

    return None




# Router Telegram v2: server.py queda como boca unica. Las reglas calculan;
# Ollama solo ayuda a clasificar cuando no hay botonera segura.
def _telegram_periodo_rango_v2(texto):
    t = _telegram_texto_norm(texto)
    hoy = date.today()
    if "ayer" in t:
        d = hoy - timedelta(days=1)
        return d.strftime("%Y-%m-%d"), hoy.strftime("%Y-%m-%d"), "ayer"
    if "semana pasada" in t:
        lunes_actual = hoy - timedelta(days=hoy.weekday())
        inicio = lunes_actual - timedelta(days=7)
        return inicio.strftime("%Y-%m-%d"), lunes_actual.strftime("%Y-%m-%d"), "semana pasada"
    if "esta semana" in t:
        inicio = hoy - timedelta(days=hoy.weekday())
        return inicio.strftime("%Y-%m-%d"), (hoy + timedelta(days=1)).strftime("%Y-%m-%d"), "esta semana"
    if "ultimos 7" in t or "ultimos siete" in t:
        fin = hoy + timedelta(days=1)
        inicio = fin - timedelta(days=7)
        return inicio.strftime("%Y-%m-%d"), fin.strftime("%Y-%m-%d"), "ultimos 7 dias"
    if "hoy" in t or "vinieron" in t:
        return hoy.strftime("%Y-%m-%d"), (hoy + timedelta(days=1)).strftime("%Y-%m-%d"), "hoy"
    if "este mes" in t or "mes" in t:
        inicio = hoy.replace(day=1)
        return inicio.strftime("%Y-%m-%d"), (hoy + timedelta(days=1)).strftime("%Y-%m-%d"), "este mes"
    periodo = _periodo_desde_texto(texto)
    inicio, fin = _rango_periodo(periodo)
    return inicio, fin, periodo


def _telegram_es_resumen_v2(t):
    return any(x in t for x in ("que paso", "resumen", "panorama", "actividad", "planta", "mostrame", "mostra", "cosas", "como venimos"))


def _telegram_es_compras_v2(t):
    return any(x in t for x in ("proveedor", "proveedores", "compra", "compras", "ingreso", "ingresos", "vino", "vinieron", "trajo", "trajeron", "entrego", "entregaron"))


def _telegram_es_produccion_v2(t):
    return any(x in t for x in ("produccion", "produjeron", "maquina", "maquinas", "operador", "operadores"))


def _telegram_es_despachos_v2(t):
    return any(x in t for x in ("despacho", "despachos", "despachamos", "despacharon", "despachado", "venta", "ventas", "cliente", "clientes", "salio", "salieron"))


def _telegram_dim_label_v2(dim):
    return {"Proveedor": "proveedor", "Maquina": "maquina", "Operador": "operador", "__material__": "material", "TiposDeMovimiento": "tipo"}.get(dim, dim)


def _telegram_top_rango_v2(where, args=(), dim="Proveedor", inicio=None, fin=None, limite=10):
    return _telegram_sql_top_rango(where, args=args, dim=dim, inicio=inicio, fin=fin, limite=limite)


def _telegram_respuesta_top_rango_v2(titulo, total_label, where, args=(), dim="Proveedor", inicio=None, fin=None, limite=10):
    data = _telegram_top_rango_v2(where, args=args, dim=dim, inicio=inicio, fin=fin, limite=limite)
    tot = _telegram_total_rango(where, args=args, inicio=inicio, fin=fin)
    total = (tot.get("row") or {}).get("kg") if tot.get("ok") else None
    return _respuesta_top_telegram(titulo, total_label, data, total)


def responder_telegram_materiales_proveedor(texto):
    prov = _extraer_proveedor_telegram(texto)
    if not prov:
        return None
    inicio, fin, etiqueta = _telegram_periodo_rango_v2(texto)
    where = _sql_tipo_compra_proveedor() + " AND UPPER(Proveedor) LIKE %s"
    like = "%" + prov.upper().replace(" ", "%") + "%"
    return _telegram_respuesta_top_rango_v2(
        f"Materiales de {prov} ({etiqueta}, compra real)",
        "Total compra real",
        where,
        args=(like,),
        dim="__material__",
        inicio=inicio,
        fin=fin,
        limite=10,
    )


def responder_telegram_compras_v2(texto):
    inicio, fin, etiqueta = _telegram_periodo_rango_v2(texto)
    t = _telegram_texto_norm(texto)
    mat = responder_telegram_materiales_proveedor(texto)
    if mat:
        return mat
    dim = "__material__" if any(x in t for x in ("material", "materiales", "trajo", "trajeron")) else "Proveedor"
    titulo = f"Compras reales por {_telegram_dim_label_v2(dim)} ({etiqueta})"
    return _telegram_respuesta_top_rango_v2(titulo, "Total compra real", _sql_tipo_compra_proveedor(), dim=dim, inicio=inicio, fin=fin, limite=12)


def responder_telegram_produccion_v2(texto):
    inicio, fin, etiqueta = _telegram_periodo_rango_v2(texto)
    t = _telegram_texto_norm(texto)
    dim = "Maquina"
    if "operador" in t or "operadores" in t:
        dim = "Operador"
    elif "material" in t or "materiales" in t:
        dim = "__material__"
    return _telegram_respuesta_top_rango_v2(
        f"Produccion por {_telegram_dim_label_v2(dim)} ({etiqueta})",
        "Total produccion",
        "UPPER(TRIM(TiposDeMovimiento)) = 'PRODUCCION'",
        dim=dim,
        inicio=inicio,
        fin=fin,
        limite=12,
    )


def responder_telegram_despachos_v2(texto):
    inicio, fin, etiqueta = _telegram_periodo_rango_v2(texto)
    t = _telegram_texto_norm(texto)
    dim = "__material__" if "material" in t or "materiales" in t else "Proveedor"
    where = "UPPER(TRIM(TiposDeMovimiento)) LIKE %s AND UPPER(TiposDeMovimiento) NOT LIKE %s"
    args = ("DESPACHO%", "%DEVOLUCION%")
    if any(x in t for x in ("cuanto", "cuantos", "total", "kilos", "kg")) and dim == "Proveedor":
        dim = "TiposDeMovimiento"
    return _telegram_respuesta_top_rango_v2(
        f"Despachos por {_telegram_dim_label_v2(dim)} ({etiqueta})",
        "Total despachado",
        where,
        args=args,
        dim=dim,
        inicio=inicio,
        fin=fin,
        limite=12,
    )


def responder_telegram_resumen_semana(texto):
    inicio, fin, etiqueta = _telegram_periodo_rango_v2(texto)
    prod = _telegram_sql_top_rango("UPPER(TRIM(TiposDeMovimiento)) = 'PRODUCCION'", dim="Maquina", inicio=inicio, fin=fin, limite=5)
    prod_tot = _telegram_total_rango("UPPER(TRIM(TiposDeMovimiento)) = 'PRODUCCION'", inicio=inicio, fin=fin)
    ing = _telegram_sql_top_rango(_sql_tipo_compra_proveedor(), dim="Proveedor", inicio=inicio, fin=fin, limite=5)
    ing_tot = _telegram_total_rango(_sql_tipo_compra_proveedor(), inicio=inicio, fin=fin)
    desp_where = "UPPER(TRIM(TiposDeMovimiento)) LIKE %s AND UPPER(TiposDeMovimiento) NOT LIKE %s"
    desp = _telegram_sql_top_rango(desp_where, args=("DESPACHO%", "%DEVOLUCION%"), dim="Proveedor", inicio=inicio, fin=fin, limite=5)
    desp_tot = _telegram_total_rango(desp_where, args=("DESPACHO%", "%DEVOLUCION%"), inicio=inicio, fin=fin)
    mov = _telegram_sql_top_rango("UPPER(TRIM(TiposDeMovimiento)) <> 'ERROR_REGISTRO'", dim="TiposDeMovimiento", inicio=inicio, fin=fin, limite=6)
    err = _telegram_total_rango("UPPER(TRIM(TiposDeMovimiento)) = 'ERROR_REGISTRO'", inicio=inicio, fin=fin)
    lineas = [f"Resumen de planta ({etiqueta}):", ""]
    lineas.append(f"Produccion: {_fmt_kg_telegram((prod_tot.get('row') or {}).get('kg') if prod_tot.get('ok') else 0)}")
    for r in (prod.get("rows") or [])[:5]:
        lineas.append(f"- {r.get('nombre')}: {_fmt_kg_telegram(r.get('kg'))}")
    lineas.append("")
    lineas.append(f"Compra real: {_fmt_kg_telegram((ing_tot.get('row') or {}).get('kg') if ing_tot.get('ok') else 0)}")
    for r in (ing.get("rows") or [])[:5]:
        lineas.append(f"- {r.get('nombre')}: {_fmt_kg_telegram(r.get('kg'))}")
    lineas.append("")
    lineas.append(f"Despachos: {_fmt_kg_telegram((desp_tot.get('row') or {}).get('kg') if desp_tot.get('ok') else 0)}")
    for r in (desp.get("rows") or [])[:5]:
        lineas.append(f"- {r.get('nombre')}: {_fmt_kg_telegram(r.get('kg'))}")
    lineas.append("")
    lineas.append("Movimientos principales (sin ERROR_REGISTRO):")
    for r in (mov.get("rows") or [])[:6]:
        lineas.append(f"- {r.get('nombre')}: {_fmt_kg_telegram(r.get('kg'))} ({int(r.get('registros') or 0)} registros)")
    err_kg = (err.get("row") or {}).get("kg") if err.get("ok") else 0
    if err_kg:
        lineas.append(f"Nota calidad: ERROR_REGISTRO {_fmt_kg_telegram(err_kg)} separado; no lo leo como actividad sana.")
    return "\n".join(lineas)




def _extraer_proveedor_historial_telegram(texto):
    t = _telegram_texto_norm(texto)
    patrones = [
        r"hablame de\s+([a-z0-9 ._-]+)",
        r"([a-z0-9 ._-]+?)\s+(?:kilos|kg)\s+por\s+mes",
        r"([a-z0-9 ._-]+?)\s+por\s+mes",
        r"historial\s+de\s+([a-z0-9 ._-]+)",
    ]
    for pat in patrones:
        m = re.search(pat, t)
        if not m:
            continue
        val = m.group(1)
        val = re.split(r"\b(hoy|ayer|semana|mes|anio|a?o|compra|compras|proveedor|proveedores|kilos|kg|historial)\b", val, 1)[0]
        val = re.sub(r"[^a-z0-9 ]+", " ", val).strip()
        if val and val not in {"de", "del", "la", "el", "un", "una", "material", "materiales"}:
            return val
    return None


def responder_telegram_proveedor_historial_v2(texto):
    prov = _extraer_proveedor_historial_telegram(texto)
    if not prov:
        return None
    conn = get_db_connection()
    if not conn:
        return "No pude conectar a la base local."
    like = "%" + prov.upper().replace(" ", "%") + "%"
    try:
        cur = conn.cursor()
        mat_expr = _telegram_material_expr(cur)
        cur.execute(f"""
            SELECT DATE_FORMAT(FechaHora, '%%Y-%%m') AS periodo,
                   ROUND(SUM(kilos), 1) AS kg,
                   COUNT(*) AS registros,
                   COUNT(DISTINCT DATE(FechaHora)) AS dias
            FROM TiposDeMovimiento
            WHERE FechaHora >= DATE_SUB(CURDATE(), INTERVAL 13 MONTH)
              AND {_sql_tipo_compra_proveedor()}
              AND Proveedor IS NOT NULL
              AND TRIM(Proveedor) <> ''
              AND UPPER(Proveedor) LIKE %s
            GROUP BY DATE_FORMAT(FechaHora, '%%Y-%%m')
            ORDER BY periodo DESC
            LIMIT 13
        """, (like,))
        meses = cur.fetchall() or []
        cur.execute(f"""
            SELECT {mat_expr} AS material,
                   ROUND(SUM(kilos), 1) AS kg,
                   COUNT(*) AS registros
            FROM TiposDeMovimiento
            WHERE FechaHora >= DATE_SUB(CURDATE(), INTERVAL 13 MONTH)
              AND {_sql_tipo_compra_proveedor()}
              AND Proveedor IS NOT NULL
              AND TRIM(Proveedor) <> ''
              AND UPPER(Proveedor) LIKE %s
            GROUP BY {mat_expr}
            ORDER BY kg DESC
            LIMIT 5
        """, (like,))
        mats = cur.fetchall() or []
        cur.execute("""
            SELECT TRIM(Proveedor) AS proveedor, ROUND(SUM(kilos), 1) AS kg
            FROM TiposDeMovimiento
            WHERE FechaHora >= DATE_SUB(CURDATE(), INTERVAL 13 MONTH)
              AND """ + _sql_tipo_compra_proveedor() + """
              AND Proveedor IS NOT NULL
              AND TRIM(Proveedor) <> ''
              AND UPPER(Proveedor) LIKE %s
            GROUP BY TRIM(Proveedor)
            ORDER BY kg DESC
            LIMIT 3
        """, (like,))
        nombres = cur.fetchall() or []
        cur.close(); conn.close()
    except Exception as e:
        try:
            conn.close()
        except Exception:
            pass
        return f"No pude armar historial de {prov}: {shorten_text(str(e), 180)}"

    if not meses:
        return f"No veo compra real de '{prov}' en los ultimos 13 meses."
    total = sum(float(r.get("kg") or 0) for r in meses)
    activos = len([r for r in meses if float(r.get("kg") or 0) > 0])
    prom = total / activos if activos else 0
    nombre = (nombres[0].get("proveedor") if nombres else prov) or prov
    lineas = [
        f"{nombre} - compra real por mes",
        f"Ultimos 13 meses: {_fmt_kg_telegram(total)} en {activos} meses activos; promedio activo {_fmt_kg_telegram(prom)}/mes.",
        "",
        "Meses:",
    ]
    for r in meses[:12]:
        lineas.append(f"- {r.get('periodo')}: {_fmt_kg_telegram(r.get('kg'))} ({int(r.get('registros') or 0)} reg, {int(r.get('dias') or 0)} dias)")
    if mats:
        lineas.append("")
        lineas.append("Materiales principales:")
        for m in mats[:5]:
            lineas.append(f"- {m.get('material')}: {_fmt_kg_telegram(m.get('kg'))}")
    return "\n".join(lineas)

def responder_telegram_deterministico(texto):
    t = _telegram_texto_norm(texto)
    consulta_operativa = _telegram_es_compras_v2(t) or _telegram_es_produccion_v2(t) or _telegram_es_despachos_v2(t) or _telegram_es_resumen_v2(t)

    if (t in ("hola", "buenas", "ola") or t.startswith("hola ")) and not consulta_operativa:
        return ("Hola. Soy el server local. Puedo responder: proveedores hoy, proveedores semana pasada, que trajo Massa, produccion por maquina, despachos por cliente, resumen semana pasada.")

    if "estado" in t or "status" in t:
        return (f"Servidor activo. Telegram inbox: {'on' if TELEGRAM_INBOX_ENABLED else 'off'}. "
                f"HTTP ingest: /api/ia/ingest/<topic>. MQTT: {'conectado' if MQTT_STATUS.get('connected') else 'sin conexion'} ({MQTT_STATUS.get('last_error') or 'sin error reciente'}).")

    hist = responder_telegram_proveedor_historial_v2(texto)
    if hist:
        return hist

    # Orden por intencion: una pregunta de proveedores con 'semana' sigue siendo compras, no resumen.
    if _telegram_es_compras_v2(t):
        return responder_telegram_compras_v2(texto)
    if _telegram_es_produccion_v2(t):
        return responder_telegram_produccion_v2(texto)
    if _telegram_es_despachos_v2(t):
        return responder_telegram_despachos_v2(texto)
    if _telegram_es_resumen_v2(t):
        return responder_telegram_resumen_semana(texto)
    return None

def responder_telegram_con_ollama(texto):
    if not TELEGRAM_INBOX_OLLAMA_ENABLED:
        return None
    prompt = f"""
Sos un clasificador liviano del servidor Ecotecnica. No inventes datos ni SQL.
Mensaje recibido por Telegram: {texto!r}
RespondÃ© SOLO JSON con: intent, respuesta_corta, necesita_datos.
Si el mensaje es ambiguo, pedÃ­ una reformulaciÃ³n concreta. MÃ¡ximo 180 caracteres.
""".strip()
    r = llamar_ollama(prompt, timeout=TELEGRAM_INBOX_OLLAMA_TIMEOUT_SECONDS, num_predict=90)
    if not r.get("ok"):
        return None
    try:
        data = json.loads(r.get("texto") or "{}")
    except Exception:
        data = {}
    resp = str(data.get("respuesta_corta") or "").strip()
    if resp:
        return shorten_text(resp, 420)
    return None


def procesar_telegram_update(update):
    msg = (update or {}).get("message") or (update or {}).get("edited_message") or {}
    texto = (msg.get("text") or "").strip()
    chat = msg.get("chat") or {}
    chat_id = str(chat.get("id") or "")
    if not texto or not chat_id:
        return
    if TELEGRAM_CHAT_ID and chat_id != str(TELEGRAM_CHAT_ID):
        TELEGRAM_INBOX_STATUS["last_error"] = f"chat no autorizado: {chat_id}"
        return
    TELEGRAM_INBOX_STATUS["last_message"] = {"chat_id": chat_id, "text": shorten_text(texto, 240), "ts": datetime.now().isoformat()}
    registrar_memoria_operativa(
        fuente="telegram",
        canal="telegram_inbox",
        tipo="pregunta_usuario",
        texto=texto,
        topic="telegram/pregunta",
        titulo="Pregunta recibida por Telegram",
        resumen=shorten_text(texto, 500),
        metadata={"chat_id": chat_id},
        utilidad_score=70,
    )

    respuesta = responder_telegram_deterministico(texto)
    if respuesta is None:
        try:
            raw = json.dumps({"origen": "telegram", "chat_id": chat_id, "texto": texto}, ensure_ascii=False).encode("utf-8")
            threading.Thread(target=procesar_mqtt_message, args=("telegram/inbox", raw, 0, False), daemon=True).start()
        except Exception:
            pass
        respuesta = responder_telegram_con_ollama(texto)
    if respuesta is None:
        respuesta = "Te leo, pero no lo tengo mapeado todavia. Probame con: proveedores hoy, compras julio, produccion hoy, despachos mes pasado."
    registrar_memoria_operativa(
        fuente="server",
        canal="telegram_outbox",
        tipo="respuesta_server",
        texto=respuesta,
        topic="telegram/respuesta",
        titulo="Respuesta enviada por Telegram",
        resumen=shorten_text(respuesta, 500),
        metadata={"chat_id": chat_id, "pregunta": texto},
        utilidad_score=55,
    )
    enviar_telegram_a(chat_id, respuesta)


def telegram_inbox_loop():
    offset = None
    TELEGRAM_INBOX_STATUS["running"] = True
    TELEGRAM_INBOX_STATUS["last_error"] = None
    if TELEGRAM_INBOX_SKIP_OLD:
        r = _telegram_api("getUpdates", {"offset": -1, "timeout": 1, "allowed_updates": ["message", "edited_message"]}, timeout=5)
        if r.get("ok") and r.get("result"):
            offset = int(r["result"][-1].get("update_id") or 0) + 1
            TELEGRAM_INBOX_STATUS["last_update_id"] = offset - 1
    while True:
        try:
            r = _telegram_api("getUpdates", {"offset": offset, "timeout": 20, "allowed_updates": ["message", "edited_message"]}, timeout=25)
            if not r.get("ok"):
                TELEGRAM_INBOX_STATUS["last_error"] = r.get("error") or str(r)
                time.sleep(max(TELEGRAM_INBOX_POLL_SECONDS, 2))
                continue
            TELEGRAM_INBOX_STATUS["last_error"] = None
            for upd in r.get("result") or []:
                uid = int(upd.get("update_id") or 0)
                offset = uid + 1
                TELEGRAM_INBOX_STATUS["last_update_id"] = uid
                try:
                    procesar_telegram_update(upd)
                except Exception as e:
                    TELEGRAM_INBOX_STATUS["last_error"] = str(e)
        except Exception as e:
            TELEGRAM_INBOX_STATUS["last_error"] = str(e)
            time.sleep(max(TELEGRAM_INBOX_POLL_SECONDS, 2))


def iniciar_telegram_inbox():
    global _TELEGRAM_INBOX_STARTED
    with _TELEGRAM_INBOX_LOCK:
        if _TELEGRAM_INBOX_STARTED:
            return
        _TELEGRAM_INBOX_STARTED = True
    if not TELEGRAM_INBOX_ENABLED:
        TELEGRAM_INBOX_STATUS.update({"enabled": False, "running": False, "last_error": "deshabilitado"})
        return
    if not TELEGRAM_BOT_TOKEN:
        TELEGRAM_INBOX_STATUS.update({"running": False, "last_error": "TELEGRAM_BOT_TOKEN no configurado"})
        return
    t = threading.Thread(target=telegram_inbox_loop, daemon=True)
    t.start()

def formatear_conclusion_telegram(conclusion, origen="ia_local"):
    columna = conclusion.get("columna") or origen
    estado = conclusion.get("estado") or "conocimiento_nuevo"
    confianza = conclusion.get("confianza")
    texto = conclusion.get("conclusion") or conclusion.get("conclusion_principal") or ""
    regla = conclusion.get("regla_aprendible") or conclusion.get("regla_aprendida") or ""
    siguiente = conclusion.get("siguiente_analisis") or ""
    anomalias = conclusion.get("anomalias") or []
    nivel = conclusion.get("nivel_interes") or nivel_interes_conclusion(conclusion)
    lineas_concretas = extraer_lineas_concretas(texto)

    partes = [
        f"Hallazgo IA ({nivel})",
        f"{columna} Â· {estado}",
    ]
    if confianza is not None:
        partes.append(f"Confianza: {confianza}")

    if lineas_concretas:
        partes.append("Dato concreto:")
        partes.extend(f"- {normalizar_numeros_texto_telegram(linea)}" for linea in lineas_concretas)
    elif texto:
        partes.append(f"Dato concreto: {shorten_text(normalizar_numeros_texto_telegram(limpiar_texto_hallazgo(texto)), 260)}")

    if regla:
        partes.append(f"Regla tentativa: {shorten_text(normalizar_numeros_texto_telegram(limpiar_texto_hallazgo(regla)), 220)}")
    if anomalias:
        partes.append("Anomalia/atencion:")
        for item in anomalias[:2]:
            detalle = formatear_anomalia_telegram(item)
            partes.append(f"- {shorten_text(normalizar_numeros_texto_telegram(detalle), 220)}")
    partes.extend(lineas_evidencia_telegram(conclusion))
    if siguiente:
        partes.append(f"Siguiente: {shorten_text(siguiente, 180)}")
    return "\n".join(partes)


def notificar_telegram_conclusion(conclusion, origen="ia_local"):
    nivel = nivel_interes_conclusion(conclusion)
    conclusion["nivel_interes"] = nivel
    firma = firma_tematica_hallazgo(conclusion)
    conclusion["firma_tematica"] = firma
    if nivel == "baja" and not TELEGRAM_NOTIFY_LOW_INTEREST:
        add_reasoning_step(
            "telegram_filtrado",
            "No envie por Telegram una conclusion de baja prioridad.",
            shorten_text(conclusion.get("conclusion"), 180)
        )
        return {"ok": False, "filtered": True, "nivel_interes": nivel}
    if telegram_firma_repetida_reciente(firma):
        add_reasoning_step(
            "telegram_filtrado",
            "No envie por Telegram una conclusion repetida por tema.",
            firma
        )
        return {"ok": False, "filtered": True, "nivel_interes": nivel, "firma_tematica": firma}
    mensaje = formatear_conclusion_telegram(conclusion, origen=origen)
    resultado = enviar_telegram(mensaje)
    if resultado.get("ok"):
        TELEGRAM_SENT_HALLAZGO_FIRMAS.add(firma)
        add_reasoning_step(
            "telegram",
            "EnviÃ© una conclusiÃ³n por Telegram.",
            conclusion.get("columna") or origen
        )
    elif not resultado.get("disabled"):
        add_reasoning_step(
            "telegram_error",
            "No pude enviar la conclusiÃ³n por Telegram.",
            resultado.get("error") or str(resultado)
        )
    return resultado


def notificar_telegram_inicio():
    if not TELEGRAM_STARTUP_NOTIFY:
        return {"ok": False, "disabled": True}

    # Esperar hasta 30s a que tailscaled termine de levantar tras el reboot.
    # Si aparece una IP 100.x antes, salimos del loop inmediatamente.
    _inicio = time.time()
    _timeout = 30
    while True:
        access_ips = get_access_ips()
        tailscale_ips = access_ips["tailscale"]
        if tailscale_ips or (time.time() - _inicio) >= _timeout:
            break
        time.sleep(2)

    lan_ips = access_ips["lan"]
    ips = access_ips["all"]
    principal_ip = tailscale_ips[0] if tailscale_ips else (lan_ips[0] if lan_ips else "127.0.0.1")
    urls = [f"http://{principal_ip}:8080/ia"]
    if TELEGRAM_COMPACT_HEADERS:
        partes = [
            "Dashboard IA conectado",
            f"{OLLAMA_MODEL} | autonomia {'activa' if AUTO_IA_ENABLED else 'inactiva'}",
            f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}",
        ]
        if tailscale_ips:
            partes.append("Tailscale: " + ", ".join(tailscale_ips))
        if lan_ips:
            partes.append("LAN: " + ", ".join(lan_ips))
        partes.append("Dashboard: " + urls[0])
        if TELEGRAM_STARTUP_ACCESS_HINTS:
            partes.append(f"SSH: ssh plapopepo@{principal_ip}")
            partes.append(f"VNC Viewer: {principal_ip}:5900")
        mensaje = "\n".join(partes)
    else:
        mensaje = "\n".join([
            "Ecotecnica IA Local",
            "Dashboard IA conectado.",
            f"Modelo: {OLLAMA_MODEL}",
            f"Autonomia: {'activa' if AUTO_IA_ENABLED else 'inactiva'}",
            f"Hora: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}",
            "Tailscale: " + (", ".join(tailscale_ips) if tailscale_ips else "no detectado"),
            "LAN: " + (", ".join(lan_ips) if lan_ips else "sin IP LAN detectada"),
            "URL: " + urls[0],
            f"SSH: ssh plapopepo@{principal_ip}",
            f"VNC Viewer: {principal_ip}:5900",
        ])
    resultado = enviar_telegram(mensaje)
    if resultado.get("ok"):
        add_reasoning_step(
            "telegram_inicio",
            "Avise por Telegram que el dashboard IA se conecto.",
            "startup"
        )
    elif not resultado.get("disabled"):
        add_reasoning_step(
            "telegram_inicio_error",
            "No pude enviar el aviso de inicio por Telegram.",
            resultado.get("error") or str(resultado)
        )
    return resultado


def notificar_telegram_inicio_async():
    t = threading.Thread(target=notificar_telegram_inicio, daemon=True)
    t.start()
    return t


_MESES_ES = ["enero", "febrero", "marzo", "abril", "mayo", "junio",
             "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"]


def _nombre_mes_es(periodo):
    """'2026-07' -> 'julio 2026'; devuelve el periodo tal cual si no parsea."""
    try:
        p = str(periodo)
        return f"{_MESES_ES[int(p[5:7]) - 1]} {p[:4]}"
    except Exception:
        return str(periodo)


def _bio_proveedor_frase(nombre_prov, bio, kg_mes=None, periodo=None):
    """Frase corta determinÃ­stica sobre un proveedor, kg primero.
    bio: fila normalizada de ia_biografia_protagonistas o None."""
    pre = f"{nombre_prov}: "
    if kg_mes is not None:
        pre += f"{int(kg_mes):,} kg" + (f" en {periodo}" if periodo else "") + "; "
    if not bio or int(bio.get("meses_con_actividad") or 0) == 0:
        return pre + "sin historial unido todavÃ­a"
    n = int(bio.get("meses_con_actividad") or 0)
    kg_prom = float(bio.get("kg_promedio_meses_activos") or 0)
    etiqueta = {
        "fuerte": "habitual fuerte",
        "media": "habitual",
        "debil": "historial dÃ©bil",
        "antecedente_unico": "un solo mes previo",
    }.get(bio.get("confiabilidad"), "historial dÃ©bil")
    return pre + f"historial unido: {n} meses activos ({etiqueta}); promedio histÃ³rico {int(kg_prom):,} kg/mes"


def _mapa_alias_proveedores_liviano():
    """Mapa de alias de proveedores con conexiÃ³n propia; {} si no se puede leer.
    Si la tabla no existe todavÃ­a (p.ej. antes del primer recÃ¡lculo de
    derivadas), la crea con su seed y reintenta."""
    try:
        conn = get_ia_connection()
        if not conn:
            return {}
        cur = conn.cursor()
        mapa, _ = cargar_alias_proveedores(cur)
        if not mapa:
            try:
                _ensure_alias_proveedores(cur)
                conn.commit()
                mapa, _ = cargar_alias_proveedores(cur)
            except Exception:
                pass
        cur.close()
        conn.close()
        return mapa
    except Exception:
        return {}


def _maquina_es_habitual_normalidad(maquina):
    """True/False segÃºn normalidad mensual de la mÃ¡quina; None si no se puede saber."""
    try:
        conn = get_ia_connection()
        if not conn:
            return None
        cur = conn.cursor()
        cur.execute(f"""
            SELECT meses_con_actividad
            FROM ia_normalidad_mensual_produccion_maquina
            WHERE entidad = %s AND criterio_version = %s
            LIMIT 1
        """, (maquina, DERIVADAS_VERSION))
        fila = cur.fetchone()
        cur.close()
        conn.close()
        if not fila:
            return False
        return int(fila.get("meses_con_actividad") or 0) >= 3
    except Exception:
        return None


def construir_mensaje_telegram_inteligente(tipo_microtarea, evidencia, cerebro):
    """Arma un mensaje Telegram masticado y accionable para las microtareas de
    estado (produccion/ingresos del mes actual). Devuelve None si el mensaje
    solo podrÃ­a decir total/vs esperado (nada enriquecible con protagonistas,
    biografÃ­as o normalidad)."""
    evidencia = evidencia or {}
    cerebro = cerebro or {}
    periodo = evidencia.get("periodo") or "?"
    total_kg = float(evidencia.get("total_kg") or 0)
    avance_pct = evidencia.get("avance_mes_pct")
    vs_esp = evidencia.get("actual_vs_esperado_pct")

    es_ingresos = "ingresos" in str(tipo_microtarea)
    es_produccion = "produccion" in str(tipo_microtarea)
    if not (es_ingresos or es_produccion):
        return None

    # Encabezado kg-primero: los kilos absolutos lideran; vs esperado se omite
    # (el % de participaciÃ³n y las proyecciones son datos secundarios).
    titulo = "ðŸ“¦ Ingresos" if es_ingresos else "ðŸ­ ProducciÃ³n"
    encabezado = f"{titulo} {_nombre_mes_es(periodo)}: {int(total_kg):,} kg registrados"
    extras = []
    if str(evidencia.get("estado_periodo") or "") == "abierto":
        extras.append("periodo abierto")
    if avance_pct is not None:
        extras.append(f"{avance_pct}% del mes")
    if extras:
        encabezado += " (" + ", ".join(extras) + ")"

    senales = []   # avisos prioritarios (âš ï¸), en orden de prioridad
    lineas = []    # contexto masticado

    # ComparaciÃ³n con el histÃ³rico ("que haga comparaciones"): estos datos ya
    # vienen calculados en la evidencia de la microtarea, sin usar el modelo.
    normal_kg = float(evidencia.get("normal_kg") or 0)
    esperado_kg = float(evidencia.get("esperado_proporcional_kg") or 0)
    meses_base = int(evidencia.get("meses_base") or 0)
    confiab = str(evidencia.get("confiabilidad_normalidad") or "")
    if normal_kg > 0:
        etiqueta_norm = ("antecedente histÃ³rico limitado"
                         if confiab in ("antecedente_unico", "debil")
                         else "normal histÃ³rico")
        comp = f"ðŸ“Š vs {etiqueta_norm}: ~{int(normal_kg):,} kg/mes ({meses_base} mes/es base)"
        if esperado_kg > 0:
            comp += f"; esperado a esta altura ~{int(esperado_kg):,} kg"
        if vs_esp is not None:
            signo = "arriba" if vs_esp >= 0 else "abajo"
            comp += f" â†’ vas {abs(vs_esp):.0f}% {signo} de lo esperado"
        lineas.append(comp)

    if es_ingresos:
        top = evidencia.get("top_proveedores") or []
        alias_tg = _mapa_alias_proveedores_liviano()
        bios = {}
        for b in ((cerebro.get("biografias_protagonistas") or {}).get("proveedores") or []):
            nombre_b = canonizar_proveedor(b.get("proveedor") or b.get("entidad"), alias_tg)
            if nombre_b:
                bios[nombre_b] = b

        # Canonizar el top por alias y re-agrupar (Sandro mengar -> Sandro Melgar)
        kg_por_canon = {}
        for t in top:
            prov = canonizar_proveedor(t.get("Proveedor"), alias_tg) or "?"
            kg_por_canon[prov] = kg_por_canon.get(prov, 0.0) + float(t.get("kilos_total") or 0)
        items = []
        for prov in sorted(kg_por_canon, key=lambda p: -kg_por_canon[p])[:3]:
            kg = kg_por_canon[prov]
            pct = round(kg / total_kg * 100, 1) if total_kg > 0 else 0
            items.append({"proveedor": prov, "kg": kg, "pct": pct})
        if items:
            # kg como magnitud principal, sin % destacado
            lineas.append("Principales kilos: " + "; ".join(
                f"{i['proveedor']} {int(i['kg']):,} kg" for i in items))

        avance_frac = float(avance_pct or 100) / 100.0
        frases_bio = []
        for i in items:
            bio = bios.get(i["proveedor"])
            sin_historia = (not bio) or int(bio.get("meses_con_actividad") or 0) == 0
            # SeÃ±al prioritaria 1 (kg primero): volumen relevante sin historial unido
            if sin_historia and i["kg"] >= TELEGRAM_ALERTA_KG_MINIMO:
                senal = f"âš ï¸ {i['proveedor']}: {int(i['kg']):,} kg registrados; sin historial unido todavÃ­a"
                if i is items[0]:
                    # SeÃ±al prioritaria 3: ranking inusual (lÃ­der del mes sin historia)
                    senal += " y lidera el mes"
                senales.append(senal)
                continue
            # SeÃ±al prioritaria 2: cambio fuerte vs histÃ³rico EN KG
            # (comparado contra el ritmo esperado segÃºn el avance del mes)
            if bio:
                kg_prom = float(bio.get("kg_promedio_meses_activos") or 0)
                n_meses = int(bio.get("meses_con_actividad") or 0)
                kg_ritmo = kg_prom * (avance_frac if avance_frac > 0 else 1)
                if kg_ritmo > 0 and (i["kg"] >= kg_ritmo * 1.5 or i["kg"] <= kg_ritmo * 0.5):
                    direccion = "muy por encima" if i["kg"] >= kg_ritmo * 1.5 else "muy por debajo"
                    senales.append(
                        f"âš ï¸ {i['proveedor']}: {int(i['kg']):,} kg en {periodo}; {direccion} de su "
                        f"ritmo histÃ³rico (promedio {int(kg_prom):,} kg/mes en {n_meses} meses)"
                    )
                    continue
            frases_bio.append(_bio_proveedor_frase(i["proveedor"], bio, kg_mes=i["kg"], periodo=periodo))
        if frases_bio:
            lineas.append("; ".join(frases_bio))

    else:  # producciÃ³n
        top_maq = evidencia.get("top_maquinas") or []
        if top_maq:
            lider = top_maq[0]
            maquina = lider.get("Maquina") or "?"
            kg_maq = float(lider.get("kilos_total") or 0)
            pct_maq = round(kg_maq / total_kg * 100, 1) if total_kg > 0 else 0
            linea = f"MÃ¡quina lÃ­der: {maquina} ({pct_maq}% del total, {int(kg_maq):,} kg)"
            habitual = _maquina_es_habitual_normalidad(maquina)
            if habitual is True:
                linea += ", habitual segÃºn su normalidad"
            elif habitual is False:
                # SeÃ±al prioritaria: lÃ­der sin normalidad previa = ranking inusual
                senales.append(f"âš ï¸ {maquina} lidera producciÃ³n sin normalidad previa (mÃ¡quina nueva o poco vista)")
            lineas.append(linea)

        # ProducciÃ³n estable no merece Telegram. Si estÃ¡ a ritmo y la mÃ¡quina lÃ­der
        # es habitual, el tablero lo puede mostrar; el celular no tiene que vibrar.
        try:
            vs_abs = abs(float(vs_esp or 0))
        except Exception:
            vs_abs = 0
        if not senales and vs_abs < 8:
            return None

    # SeÃ±al prioritaria 4: ficha operativa interesante del periodo.
    # Solo se agrega a ingresos: meter fichas de proveedores en producciÃ³n ensucia
    # la lectura y fue justamente lo que volviÃ³ ruidoso Telegram.
    if es_ingresos:
        try:
            for f in ((cerebro.get("fichas_operativas") or {}).get("recientes") or [])[:3]:
                sen = f.get("senales_json") or {}
                if f.get("periodo") == periodo and (
                    sen.get("monoproveedor") or sen.get("dominante_concentra_mas_50pct")
                    or sen.get("es_lider_mes") or not sen.get("tiene_biografia", True)
                ):
                    lineas.append(f"Ficha: {f.get('titulo')}")
                    break
        except Exception:
            pass
    # Sin protagonistas, biografÃ­as ni normalidad: el mensaje serÃ­a solo
    # total/vs esperado -> no accionable, no enviar.
    if not senales and not lineas:
        return None

    return "\n".join([encabezado] + senales + lineas)


_TELEGRAM_REPORTES_PREVIOS = {}


def _firma_reporte_operativo(nombre, periodo, evidencia, mensaje):
    """Firma del reporte operativo para dedupe: tipo + periodo + top 3 de
    proveedores/mÃ¡quinas + diagnÃ³sticos principales (âš ï¸) sin nÃºmeros.
    Devuelve (firma, total_kg)."""
    ev = evidencia or {}
    top = ev.get("top_proveedores") or ev.get("top_maquinas") or []
    nombres_top = tuple(
        str(t.get("Proveedor") or t.get("Maquina") or "?") for t in top[:3]
    )
    diagnosticos = tuple(sorted(
        re.sub(r"[\d.,:%()+\-]", "", ln).strip()
        for ln in str(mensaje or "").split("\n") if ln.startswith("âš ï¸")
    ))
    firma = (str(nombre), str(periodo), nombres_top, diagnosticos)
    return firma, float(ev.get("total_kg") or 0)


def notificar_telegram_microtarea(nombre, periodo, avance_pct, total_kg,
                                   vs_esperado_pct, confianza, conclusion_txt,
                                   evidencia=None, cerebro=None):
    """EnvÃ­a notificaciÃ³n Telegram para observaciÃ³n de microtarea si califica.
    Regla: (abs(vs_esperado_pct) >= 25 o confianza >= 0.75) Y ademÃ¡s el mensaje
    se puede enriquecer con protagonistas/biografÃ­a/normalidad; un mensaje que
    solo dirÃ­a total/vs esperado no se envÃ­a.
    Registra reasoning_step tanto si filtra como si envÃ­a o falla."""
    # Llegar aca ya implica que la firma operativa cambio (hubo un movimiento
    # material real, "una cosa que paso"): avisamos siempre que haya actividad.
    # El dedupe de mas abajo evita reenviar un parte identico al anterior.
    # Antes exigiamos un desvio de >=25% o confianza >=0.75, lo que silenciaba
    # practicamente todos los meses normales y dejaba a Diego sin partes.
    hay_actividad = float((evidencia or {}).get("total_kg") or total_kg or 0) > 0
    califica = hay_actividad or (abs(vs_esperado_pct or 0) >= 12) or (confianza >= 0.6)
    if not califica:
        add_reasoning_step(
            "telegram_microtarea_filtrado",
            f"{nombre}: no notifica (sin actividad; vs_esp={vs_esperado_pct} conf={confianza})",
            None
        )
        return

    mensaje = construir_mensaje_telegram_inteligente(nombre, evidencia, cerebro)
    if mensaje is None:
        add_reasoning_step(
            "telegram_microtarea_filtrado",
            f"{nombre}: no notifica",
            "sin lectura accionable"
        )
        return

    # Dedupe: no reenviar si el reporte es esencialmente igual al anterior
    # (mismo top 3 y diagnÃ³sticos, y kilos sin cambio material). Cambios de
    # avance_mes_pct / vs_esperado por paso del tiempo no cuentan como cambio.
    # El umbral es deliberadamente alto: Telegram es para novedad operativa,
    # no para repetir que producciÃ³n sigue a ritmo con unos kilos mÃ¡s.    firma, kg_reporte = _firma_reporte_operativo(nombre, periodo, evidencia, mensaje)
    previo = _TELEGRAM_REPORTES_PREVIOS.get((nombre, periodo))
    if previo and previo.get("firma") == firma:
        delta_kg = abs(kg_reporte - float(previo.get("total_kg") or 0))
        pct_delta = (delta_kg / previo["total_kg"] * 100) if previo.get("total_kg") else 100.0
        if delta_kg < TELEGRAM_DEDUPE_KG_DELTA and pct_delta < TELEGRAM_DEDUPE_PCT_DELTA:
            add_reasoning_step(
                "telegram_dedupe_skip",
                f"{nombre}: reporte equivalente al anterior; no reenvÃ­o a Telegram.",
                f"periodo={periodo} delta_kg={delta_kg:,.0f} ({pct_delta:.1f}%); mismo top y diagnÃ³sticos"
            )
            return
    _TELEGRAM_REPORTES_PREVIOS[(nombre, periodo)] = {"firma": firma, "total_kg": kg_reporte}

    def _enviar():
        try:
            resultado = enviar_telegram(mensaje)
            if resultado and resultado.get("ok"):
                add_reasoning_step(
                    "telegram_microtarea_enviado",
                    f"{nombre}: Telegram enviado",
                    f"periodo={periodo} vs_esp={vs_esperado_pct} conf={confianza}"
                )
            else:
                add_reasoning_step(
                    "telegram_microtarea_error",
                    f"{nombre}: Telegram fallÃ³",
                    str(resultado)[:200] if resultado else "sin respuesta"
                )
        except Exception as ex:
            add_reasoning_step(
                "telegram_microtarea_error",
                f"{nombre}: excepciÃ³n al enviar Telegram",
                str(ex)[:200]
            )

    threading.Thread(target=_enviar, daemon=True).start()


def get_column_evidence(columna):
    if not columna:
        return None

    conn = get_db_connection()
    if not conn:
        return {"error": "No se pudo conectar a sh_etp_v2_local"}

    try:
        cur = conn.cursor()
        columnas = get_table_columns(cur, "TiposDeMovimiento")
        if columna not in columnas:
            return {"error": f"La columna {columna} no existe en TiposDeMovimiento"}

        quoted = "`" + columna.replace("`", "``") + "`"
        cur.execute(f"""
            SELECT
                COUNT(*) AS total,
                SUM(CASE WHEN {quoted} IS NULL OR {quoted} = '' THEN 1 ELSE 0 END) AS vacios,
                COUNT(DISTINCT {quoted}) AS distintos
            FROM TiposDeMovimiento
        """)
        resumen = cur.fetchone() or {}

        cur.execute(f"""
            SELECT {quoted} AS valor, COUNT(*) AS cantidad
            FROM TiposDeMovimiento
            WHERE {quoted} IS NOT NULL
              AND {quoted} <> ''
            GROUP BY {quoted}
            ORDER BY cantidad DESC
            LIMIT 8
        """)
        frecuentes = cur.fetchall()

        cur.execute(f"""
            SELECT
                TiposDeMovimiento AS tipo_movimiento,
                CASE WHEN {quoted} IS NULL OR {quoted} = '' THEN 'vacio' ELSE 'con_valor' END AS estado_columna,
                COUNT(*) AS registros,
                ROUND(SUM(kilos), 2) AS kilos
            FROM TiposDeMovimiento
            GROUP BY TiposDeMovimiento, estado_columna
            ORDER BY registros DESC
            LIMIT 20
        """)
        contexto_movimiento = cur.fetchall()

        cur.execute(f"""
            SELECT
                TiposDeMovimiento AS tipo_movimiento,
                COUNT(*) AS registros,
                ROUND(SUM(kilos), 2) AS kilos,
                ROUND(AVG(CASE WHEN {quoted} IS NULL OR {quoted} = '' THEN 1 ELSE 0 END) * 100, 1) AS pct_vacio
            FROM TiposDeMovimiento
            GROUP BY TiposDeMovimiento
            ORDER BY registros DESC
            LIMIT 12
        """)
        resumen_por_movimiento = cur.fetchall()

        cur.close()
        conn.close()
        return {
            "total": resumen.get("total") or 0,
            "vacios": resumen.get("vacios") or 0,
            "distintos": resumen.get("distintos") or 0,
            "frecuentes": frecuentes,
            "contexto_movimiento": contexto_movimiento,
            "resumen_por_movimiento": resumen_por_movimiento,
        }

    except Exception as e:
        print(f"Error en get_column_evidence: {e}", file=sys.stderr)
        return {"error": str(e)}
    finally:
        try:
            conn.close()
        except Exception:
            pass


def parse_model_json(text):
    if not text:
        return None
    raw = text.strip()
    try:
        return json.loads(raw)
    except Exception:
        pass

    start = raw.find("{")
    end = raw.rfind("}")
    if start >= 0 and end > start:
        try:
            return json.loads(raw[start:end + 1])
        except Exception:
            return None
    return None


def extraer_json_modelo(text):
    """Devuelve {ok,data,error,raw,fragment}; no inventa JSON si esta incompleto."""
    raw = (text or "").strip()
    if not raw:
        return {"ok": False, "data": None, "error": "respuesta_vacia", "raw": raw, "fragment": ""}
    try:
        return {"ok": True, "data": json.loads(raw), "error": None, "raw": raw, "fragment": raw}
    except Exception as e_full:
        full_error = str(e_full)
    start = raw.find("{")
    end = raw.rfind("}")
    if start >= 0 and end > start:
        fragment = raw[start:end + 1]
        try:
            return {"ok": True, "data": json.loads(fragment), "error": None, "raw": raw, "fragment": fragment}
        except Exception as e_fragment:
            return {"ok": False, "data": None, "error": f"json_fragmento_invalido: {e_fragment}", "raw": raw, "fragment": fragment}
    if start >= 0 and end < start:
        return {"ok": False, "data": None, "error": "json_incompleto_sin_llave_cierre", "raw": raw, "fragment": raw[start:]}
    return {"ok": False, "data": None, "error": f"sin_objeto_json: {full_error}", "raw": raw, "fragment": ""}


def extraer_decision_parcial_estructural(text):
    """Recupera una conclusion util cuando Ollama corta un JSON casi valido."""
    raw = str(text or "").strip()
    if not raw:
        return None

    def _campo_texto(*nombres):
        for nombre in nombres:
            m = re.search(
                rf'"{nombre}"\s*:\s*"(?P<v>(?:\\.|[^"\\])*)',
                raw,
                flags=re.IGNORECASE | re.DOTALL,
            )
            if m:
                try:
                    return m.group("v").encode("utf-8", "ignore").decode("unicode_escape", "ignore").strip()
                except Exception:
                    return m.group("v").strip()
        return None

    conclusion = _campo_texto("conclusion", "conclusion_principal", "interpretacion", "resumen", "hipotesis_nueva", "hipotesis")
    if not conclusion:
        # Fallback texto plano: usar la primera frase razonable si el modelo obedecio a medias.
        limpio = re.sub(r"```.*?```", "", raw, flags=re.DOTALL)
        limpio = re.sub(r'^\s*\{?\s*"?(action|conclusion|confianza|evidencia)"?\s*:?', "", limpio, flags=re.IGNORECASE).strip()
        conclusion = shorten_text(limpio, 260) if len(limpio) >= 30 else None
    if not conclusion:
        return None

    conf = None
    m_conf = re.search(r'"confianza"\s*:\s*(?P<v>0(?:\.\d+)?|1(?:\.0+)?)', raw, flags=re.IGNORECASE)
    if m_conf:
        conf = confianza_float(m_conf.group("v"))
    if conf is None:
        conf = 0.58
    conf = max(0.50, min(0.62, conf))
    return {
        "action": "conclude",
        "conclusion": shorten_text(conclusion, 320),
        "confianza": conf,
        "parse_parcial": True,
        "evidencia": "recuperado de JSON parcial del modelo",
    }


def texto_modelo_util_no_json(text):
    t = str(text or "").strip()
    if len(t) < 20:
        return False
    pistas = ["hipotes", "conclusion", "razon", "anom", "error", "falt", "precio", "proveedor", "maquina", "descuento", "produccion"]
    tl = t.lower()
    return any(p in tl for p in pistas)




