def _memoria_hash(fuente, canal, tipo, texto, payload_json=None):
    base = {
        "fuente": fuente,
        "canal": canal,
        "tipo": tipo,
        "texto": shorten_text(texto or "", 3000),
        "payload": payload_json if isinstance(payload_json, (dict, list)) else None,
    }
    raw = json.dumps(base, ensure_ascii=False, sort_keys=True, default=json_default_mqtt)
    return hashlib.sha256(raw.encode("utf-8", "ignore")).hexdigest()


