def _inferir_periodo_texto(texto, payload_json=None):
    if isinstance(payload_json, dict):
        for k in ("periodo", "mesKey", "mes", "period"):
            v = payload_json.get(k)
            if v:
                m = re.search(r"20\d{2}-\d{2}", str(v))
                if m:
                    return m.group(0)
        meta = payload_json.get("meta") or {}
        if isinstance(meta, dict):
            v = meta.get("mesKey") or meta.get("periodo")
            if v:
                m = re.search(r"20\d{2}-\d{2}", str(v))
                if m:
                    return m.group(0)
    m = re.search(r"20\d{2}-\d{2}", str(texto or ""))
    if m:
        return m.group(0)
    return datetime.now().strftime("%Y-%m")


def _extraer_metricas_reporte_textual(texto):
    s = str(texto or "")
    clean = s.replace("\r", "\n")
    metricas = {"maquinas": [], "islas": [], "totales": {}}
    for linea in clean.split("\n"):
        l = linea.strip().strip("* ")
        if not l:
            continue
        m = re.search(r"(?:[^A-Za-z0-9]\s*)?([A-Z0-9 _.-]{3,})\s*:\s*([\d.,]+)\s*kilos?", l, re.I)
        if m:
            nombre = m.group(1).strip().strip('"')
            try:
                kg = float(m.group(2).replace(".", "").replace(",", "."))
            except Exception:
                kg = None
            if kg is not None:
                if "total" in nombre.lower():
                    metricas["islas"].append({"nombre": nombre, "kg": kg})
                else:
                    metricas["maquinas"].append({"nombre": nombre, "kg": kg})
            continue
        mh = re.search(r"Horas Transcurridas.*?:\s*([\d.,]+)\s*horas?", l, re.I)
        if mh:
            metricas["totales"]["horas_transcurridas"] = float(mh.group(1).replace(".", "").replace(",", "."))
        mt = re.search(r"Total de Kilos.*?:\s*([\d.,]+)\s*kilos?", l, re.I)
        if mt:
            metricas["totales"]["kg_total"] = float(mt.group(1).replace(".", "").replace(",", "."))
        mp = re.search(r"Promedio.*?:\s*([\d.,]+)\s*kilos?/hora", l, re.I)
        if mp:
            metricas["totales"]["kg_hora"] = float(mp.group(1).replace(".", "").replace(",", "."))
    if not metricas["maquinas"] and not metricas["islas"] and not metricas["totales"]:
        return None
    return metricas


def clasificar_memoria_entrada(fuente, canal, topic, texto, payload_json=None):
    t = (str(topic or "") + " " + str(texto or "")[:4000]).lower()
    periodo = _inferir_periodo_texto(texto, payload_json)
    metadata = {}
    tipo = "entrada_generica"
    titulo = "Entrada operativa recibida"
    resumen = shorten_text(texto or json.dumps(payload_json, ensure_ascii=False, default=json_default_mqtt), 500)
    score = 45
    if isinstance(payload_json, dict):
        pt = str(payload_json.get("tipo") or "").lower()
        archivo = payload_json.get("archivo") or ""
        hash_corto = str(payload_json.get("hash") or "")[:10]
        origen = payload_json.get("origen") or fuente
        data = payload_json.get("data")
        metadata.update({
            "archivo": archivo,
            "hash": payload_json.get("hash"),
            "origen": origen,
            "tipo_payload": payload_json.get("tipo"),
            "generado_en": payload_json.get("generadoEn") or payload_json.get("generado_en"),
        })
        if isinstance(data, dict):
            metadata["data_keys"] = list(data.keys())[:30]
            metadata["data_tipo"] = data.get("tipo")
            metadata["data_mesKey"] = data.get("mesKey") or data.get("periodo")
        if "plan" in pt and "compra" in pt:
            tipo = "plan_compras"
            titulo = "Plan de compras recibido"
            partes = []
            if archivo:
                partes.append(str(archivo).split("/")[-1])
            if periodo:
                partes.append(f"periodo {periodo}")
            if isinstance(data, dict):
                partes.append("claves " + ", ".join(list(data.keys())[:8]))
            if hash_corto:
                partes.append("hash " + hash_corto)
            resumen = " ? ".join(partes) if partes else resumen
            score = 85
        elif "stock" in pt or "stock" in payload_json:
            tipo = "stock_snapshot"
            titulo = "Snapshot de stock recibido"
            score = 75
        elif "agenda" in pt or "agenda" in payload_json:
            tipo = "agenda_compras"
            titulo = "Agenda de compras recibida"
            score = 70
    metricas = _extraer_metricas_reporte_textual(texto)
    if metricas:
        metadata["metricas_extraidas"] = metricas
        if "produccion" in t or "producci?n" in t:
            tipo = "reporte_produccion_textual"
            titulo = "Reporte textual de produccion recibido"
            total = (metricas.get("totales") or {}).get("kg_total")
            resumen = f"Reporte de produccion textual" + (f": {int(total):,} kg total" if total else "")
            score = 80
    elif "compra" in t or "proveedor" in t:
        tipo = "reporte_compras_textual"
        titulo = "Reporte textual de compras recibido"
        score = max(score, 65)
    elif "despacho" in t or "cliente" in t:
        tipo = "reporte_despachos_textual"
        titulo = "Reporte textual de despachos recibido"
        score = max(score, 65)
    return {"tipo": tipo, "periodo": periodo, "titulo": titulo, "resumen": resumen, "metadata": metadata, "utilidad_score": score}



