def leer_composicion_operativa(max_por_tipo=12):
    """ComposiciÃ³n operativa del mes: fichas fractales de mÃ¡quinas, operadores
    y materiales normalizados comprados (perfil_maquina_historico /
    perfil_operador_historico / perfil_material_normalizado_historico) del
    periodo mÃ¡s reciente. DeterminÃ­stico, solo lectura de ia_fichas_operativas."""
    resultado = {"periodo": None, "avance_mes_pct": None,
                 "maquinas": [], "operadores": [], "materiales_normalizados": []}
    try:
        conn = get_ia_connection()
        if not conn:
            return resultado
        cur = conn.cursor()
        cur.execute(f"""
            SELECT tipo_tarea, entidad, periodo, resumen_deterministico,
                   datos_json, senales_json, creado_en
            FROM ia_fichas_operativas
            WHERE tipo_tarea IN ('perfil_maquina_historico','perfil_operador_historico',
                                 'perfil_material_normalizado_historico')
            ORDER BY creado_en DESC, id DESC
            LIMIT 300
        """)
        filas = cur.fetchall() or []
        cur.close()
        conn.close()
        if not filas:
            return resultado

        periodo = max(str(f.get("periodo") or "") for f in filas)
        resultado["periodo"] = periodo or None

        maquinas_por_operador = {}
        operadores_por_maquina = {}
        materiales_por_maquina = {}
        try:
            yr, mo = int(periodo[:4]), int(periodo[5:7])
            inicio = f"{periodo}-01"
            ultimo_dia = (date(yr, mo % 12 + 1, 1) - timedelta(days=1)) if mo < 12 else date(yr, 12, 31)
            fin_excl = (ultimo_dia + timedelta(days=1)).strftime("%Y-%m-%d")
            conn_op = get_db_connection()
            if conn_op:
                cur_op = conn_op.cursor()
                cur_op.execute("""
                    SELECT Operador, Maquina,
                           COUNT(*) AS registros,
                           COALESCE(SUM(kilos), 0) AS kg
                    FROM TiposDeMovimiento
                    WHERE FechaHora >= %s AND FechaHora < %s
                      AND TiposDeMovimiento = 'PRODUCCION'
                      AND Operador IS NOT NULL AND TRIM(Operador) <> ''
                      AND Maquina IS NOT NULL AND TRIM(Maquina) <> ''
                    GROUP BY Operador, Maquina
                    ORDER BY Operador, kg DESC
                """, (inicio, fin_excl))
                for r in (cur_op.fetchall() or []):
                    op = str(r.get("Operador") or "").strip()
                    maq = str(r.get("Maquina") or "").strip()
                    if not op or not maq:
                        continue
                    item_cruce = {
                        "maquina": maq,
                        "operador": op,
                        "kg": round(float(r.get("kg") or 0), 2),
                        "registros": int(r.get("registros") or 0),
                    }
                    maquinas_por_operador.setdefault(op.lower(), []).append(item_cruce)
                    operadores_por_maquina.setdefault(maq.lower(), []).append(item_cruce)

                cur_op.execute("""
                    SELECT Maquina,
                           COALESCE(NULLIF(TRIM(DescriptionNormalizada), ''),
                                    NULLIF(TRIM(Description), ''),
                                    NULLIF(TRIM(Materiales), '')) AS material,
                           COUNT(*) AS registros,
                           COALESCE(SUM(kilos), 0) AS kg
                    FROM TiposDeMovimiento
                    WHERE FechaHora >= %s AND FechaHora < %s
                      AND TiposDeMovimiento = 'PRODUCCION'
                      AND Maquina IS NOT NULL AND TRIM(Maquina) <> ''
                    GROUP BY Maquina, material
                    HAVING material IS NOT NULL AND material <> ''
                    ORDER BY Maquina, kg DESC
                """, (inicio, fin_excl))
                for r in (cur_op.fetchall() or []):
                    maq = str(r.get("Maquina") or "").strip()
                    mat = str(r.get("material") or "").strip()
                    if not maq or not mat:
                        continue
                    materiales_por_maquina.setdefault(maq.lower(), []).append({
                        "material": mat,
                        "kg": round(float(r.get("kg") or 0), 2),
                        "registros": int(r.get("registros") or 0),
                    })
                cur_op.close()
                conn_op.close()
        except Exception as e_om:
            print(f"Error en leer_composicion_operativa cruces_produccion: {e_om}", file=sys.stderr)
            maquinas_por_operador = {}
            operadores_por_maquina = {}
            materiales_por_maquina = {}
        hoy = date.today()
        if periodo == hoy.strftime("%Y-%m"):
            import calendar as _cal
            dias_mes = _cal.monthrange(hoy.year, hoy.month)[1]
            resultado["avance_mes_pct"] = round(hoy.day / dias_mes * 100, 1)

        vistos = set()
        for f in filas:
            if str(f.get("periodo") or "") != periodo:
                continue
            nombre = (f.get("entidad") or "").strip()
            clave = (f.get("tipo_tarea"), nombre.lower())
            if clave in vistos:
                continue  # ya tenemos la ficha mÃ¡s nueva de esta entidad
            vistos.add(clave)
            try:
                datos = json.loads(f.get("datos_json") or "{}") if isinstance(f.get("datos_json"), str) else (f.get("datos_json") or {})
            except Exception:
                datos = {}
            try:
                senales = json.loads(f.get("senales_json") or "{}") if isinstance(f.get("senales_json"), str) else (f.get("senales_json") or {})
            except Exception:
                senales = {}
            kg_prom = float(datos.get("kg_promedio_meses_previos") or 0)
            item = {
                "nombre": nombre,
                "kg_mes": round(float(datos.get("kg_actual") or 0), 1),
                "meses_historial": int(datos.get("meses_previos") or 0),
                "kg_promedio_historico": round(kg_prom, 1),
                "historial_12m": datos.get("historial_12m") or [],
                "senales": senales,
                "resumen": f.get("resumen_deterministico") or "",
                "creado_en": str(f.get("creado_en") or ""),
            }
            # Con mes en curso, el promedio histÃ³rico se prorratea por avance
            # para no comparar un mes parcial contra meses completos.
            if resultado["avance_mes_pct"] and kg_prom > 0:
                esperado = kg_prom * resultado["avance_mes_pct"] / 100.0
                item["kg_esperado_a_la_fecha"] = round(esperado, 1)
                item["desvio_pct_vs_ritmo"] = round((item["kg_mes"] - esperado) / esperado * 100, 1)
            tipo_tarea = f.get("tipo_tarea")
            if tipo_tarea == "perfil_operador_historico":
                item["tipos_principales"] = [
                    {"tipo": t.get("tipo"), "kg": t.get("kg")}
                    for t in (datos.get("tipos_principales") or [])[:3]
                ]
                item["maquinas_produccion"] = maquinas_por_operador.get(nombre.lower(), [])[:12]
                destino = resultado["operadores"]
            elif tipo_tarea == "perfil_material_normalizado_historico":
                item["material_normalizado"] = True
                actual_hist = next((h for h in item["historial_12m"]
                                    if str(h.get("periodo")) == periodo), None)
                monto = float((actual_hist or {}).get("monto") or 0)
                if monto > 0:
                    item["monto_estimado_mes"] = round(monto, 2)
                destino = resultado["materiales_normalizados"]
            else:
                item["operadores_produccion"] = operadores_por_maquina.get(nombre.lower(), [])[:12]
                item["materiales_produccion"] = materiales_por_maquina.get(nombre.lower(), [])[:12]
                destino = resultado["maquinas"]
            if len(destino) < int(max_por_tipo):
                destino.append(item)
        resultado["maquinas"].sort(key=lambda x: -x["kg_mes"])
        resultado["operadores"].sort(key=lambda x: -x["kg_mes"])
        resultado["materiales_normalizados"].sort(key=lambda x: -x["kg_mes"])
    except Exception as e:
        print(f"Error en leer_composicion_operativa: {e}", file=sys.stderr)
    return resultado


def leer_feed_operativo_reciente(limite=80):
    """Feed operativo determinÃ­stico: mezcla eventos de compras por material
    normalizado, proveedorâ†’material, calidad (ERROR_REGISTRO), precio faltante,
    protagonistas y fichas/cola recientes. Ordena lo nuevo primero (por dÃ­a) y
    dentro de cada dÃ­a prioridad kg-first. Sin Ollama."""
    items = []

    def _evt(tipo, titulo, detalle, ts=None, periodo=None, proveedor=None,
             material=None, kg=0, monto=None, precio_pond=None, registros=0):
        kg = round(float(kg or 0), 2)
        monto = round(float(monto), 2) if monto else None
        prioridad = round(kg * 0.7 + (monto or 0) * 0.001 + registros * 5.0, 4)
        items.append({
            "ts": str(ts) if ts else None,
            "periodo": periodo,
            "tipo": tipo,
            "titulo": titulo,
            "detalle": detalle,
            "proveedor": proveedor,
            "material_normalizado": material,
            "kg": kg,
            "monto": monto,
            "precio_pond": round(float(precio_pond), 4) if precio_pond else None,
            "prioridad": prioridad,
        })

    def _kg_txt(v):
        return f"{float(v or 0):,.0f} kg".replace(",", ".")

    try:
        conn = get_ia_connection()
        if not conn:
            return {"items": [], "total": 0}
        cur = conn.cursor()

        # Ãšltimos 2 periodos con datos normalizados
        cur.execute(f"""
            SELECT DISTINCT periodo FROM ia_resumen_mensual_material_normalizado_tipo
            WHERE criterio_version = %s ORDER BY periodo DESC LIMIT 2
        """, (DERIVADAS_VERSION,))
        periodos_recientes = [r["periodo"] for r in (cur.fetchall() or [])]

        if periodos_recientes:
            marcas = ", ".join(["%s"] * len(periodos_recientes))

            # 1) Compras por material normalizado (solo comprables), kg-first
            cur.execute(f"""
                SELECT periodo, material_normalizado, tipo_movimiento,
                       SUM(registros) AS registros, SUM(kilos_total) AS kg,
                       SUM(COALESCE(monto_estimado, 0)) AS monto,
                       MAX(precio_ponderado_kg) AS precio_pond,
                       MAX(ultimo_movimiento) AS ultimo_movimiento
                FROM ia_resumen_mensual_material_normalizado_tipo
                WHERE criterio_version = %s AND periodo IN ({marcas})
                  AND {_sql_tipo_compra_proveedor('tipo_movimiento')}
                GROUP BY periodo, material_normalizado, tipo_movimiento
                ORDER BY periodo DESC, kg DESC
                LIMIT 25
            """, [DERIVADAS_VERSION] + periodos_recientes)
            for r in (cur.fetchall() or []):
                kg = float(r["kg"] or 0)
                monto = float(r["monto"] or 0)
                detalle = f"{_kg_txt(kg)} vÃ­a {r['tipo_movimiento']} en {r['periodo']}"
                if monto > 0:
                    detalle += f" Â· $est {monto:,.0f}".replace(",", ".")
                _evt("compra_material", f"Compra: {r['material_normalizado']}", detalle,
                     ts=r["ultimo_movimiento"], periodo=r["periodo"],
                     material=r["material_normalizado"], kg=kg,
                     monto=monto, precio_pond=r["precio_pond"],
                     registros=int(r["registros"] or 0))
                # 4) Precio faltante: compra con volumen y sin ningÃºn precio
                if kg >= 500 and monto <= 0:
                    _evt("precio_faltante", f"Sin precio: {r['material_normalizado']}",
                         f"{_kg_txt(kg)} comprados en {r['periodo']} sin precio registrado",
                         ts=r["ultimo_movimiento"], periodo=r["periodo"],
                         material=r["material_normalizado"], kg=kg,
                         registros=int(r["registros"] or 0))

            # 2) Proveedor â†’ material normalizado
            cur.execute(f"""
                SELECT periodo, proveedor, material_normalizado,
                       SUM(registros) AS registros, SUM(kilos_total) AS kg,
                       SUM(COALESCE(monto_estimado, 0)) AS monto,
                       MAX(precio_ponderado_kg) AS precio_pond,
                       MAX(pct_kilos_del_material) AS pct_material,
                       MAX(ultimo_movimiento) AS ultimo_movimiento
                FROM ia_resumen_mensual_proveedor_material_normalizado
                WHERE criterio_version = %s AND periodo IN ({marcas})
                  AND {_sql_tipo_compra_proveedor('tipo_movimiento')}
                GROUP BY periodo, proveedor, material_normalizado
                ORDER BY periodo DESC, kg DESC
                LIMIT 20
            """, [DERIVADAS_VERSION] + periodos_recientes)
            for r in (cur.fetchall() or []):
                kg = float(r["kg"] or 0)
                monto = float(r["monto"] or 0)
                pct = float(r["pct_material"] or 0)
                detalle = f"{_kg_txt(kg)} en {r['periodo']}"
                if pct > 0:
                    detalle += f" ({pct:.0f}% del material)"
                if monto > 0:
                    detalle += f" Â· $est {monto:,.0f}".replace(",", ".")
                _evt("proveedor_material",
                     f"{r['proveedor']} â†’ {r['material_normalizado']}", detalle,
                     ts=r["ultimo_movimiento"], periodo=r["periodo"],
                     proveedor=r["proveedor"], material=r["material_normalizado"],
                     kg=kg, monto=monto, precio_pond=r["precio_pond"],
                     registros=int(r["registros"] or 0))

        # 6) Fichas operativas recientes (Ãºltimos 7 dÃ­as)
        cur.execute(f"""
            SELECT titulo, resumen_deterministico, entidad, entidad_2, tipo_nodo,
                   periodo, creado_en
            FROM ia_fichas_operativas
            WHERE creado_en >= DATE_SUB(NOW(), INTERVAL 7 DAY)
            ORDER BY creado_en DESC, id DESC
            LIMIT 15
        """)
        for r in (cur.fetchall() or []):
            prov = r["entidad_2"] if r["tipo_nodo"] in ("proveedor_material",) else (
                r["entidad"] if r["tipo_nodo"] == "proveedor" else None)
            mat = r["entidad"] if r["tipo_nodo"] in ("material", "proveedor_material") else None
            _evt("ficha", r["titulo"] or "Ficha operativa",
                 r["resumen_deterministico"] or "", ts=r["creado_en"],
                 periodo=r["periodo"], proveedor=prov, material=mat)

        # 7) Cola: curiosidades encoladas recientes aÃºn pendientes (novedad)
        cur.execute(f"""
            SELECT tipo_tarea, entidad, entidad_2, periodo, motivo,
                   prioridad_score, creado_en
            FROM ia_cola_curiosidad
            WHERE estado = 'pendiente'
              AND creado_en >= DATE_SUB(NOW(), INTERVAL 2 DAY)
            ORDER BY prioridad_score DESC
            LIMIT 10
        """)
        for r in (cur.fetchall() or []):
            _evt("cola", f"Curiosidad encolada: {r['entidad']}",
                 r["motivo"] or r["tipo_tarea"], ts=r["creado_en"],
                 periodo=r["periodo"])
        cur.close()
        conn.close()
    except Exception as e:
        print(f"Error en leer_feed_operativo_reciente (lab): {e}", file=sys.stderr)

    # 3) Calidad: ERROR_REGISTRO del mes actual
    try:
        calidad = leer_calidad_error_registro(limite=3)
        if ERROR_REGISTRO_EN_FEED and float(calidad.get("kilos_total") or 0) > 0:
            _evt("calidad",
                 f"ERROR_REGISTRO: {_kg_txt(calidad['kilos_total'])} en {calidad['periodo']}",
                 (f"{calidad['registros']} registros marcados como error"
                  + (f"; {calidad['sin_proveedor']} sin proveedor" if calidad.get("sin_proveedor") else "")),
                 periodo=calidad["periodo"], kg=calidad["kilos_total"],
                 registros=int(calidad.get("registros") or 0))
            for m in (calidad.get("top_materiales") or []):
                _evt("calidad",
                     f"ERROR_REGISTRO: {m.get('material_normalizado') or 'sin descripciÃ³n'}",
                     f"{_kg_txt(m.get('kilos'))} en {m.get('registros')} registros",
                     periodo=calidad["periodo"], material=m.get("material_normalizado"),
                     kg=m.get("kilos"), registros=int(m.get("registros") or 0))
    except Exception as e:
        print(f"Error en feed calidad: {e}", file=sys.stderr)

    # 5) Protagonistas operativos (nivel 1)
    try:
        prot = leer_protagonistas_operativos()
        for r in (prot.get("nivel1") or [])[:8]:
            etiqueta = r.get("etiqueta") or r.get("entidad") or "?"
            kg = float(r.get("kg_entidad") or 0)
            pct = float(r.get("pct_del_contexto") or 0)
            _evt("protagonista", f"Protagonista: {etiqueta}",
                 f"{_kg_txt(kg)} en {r.get('periodo')}" + (f" ({pct:.0f}% del contexto)" if pct else ""),
                 ts=r.get("actualizado_en"), periodo=r.get("periodo"),
                 proveedor=r.get("proveedor"), material=r.get("material"),
                 kg=kg, registros=int(r.get("registros") or 0))
    except Exception as e:
        print(f"Error en feed protagonistas: {e}", file=sys.stderr)

    # Orden: lo nuevo primero (dÃ­a del ts, o periodo si no hay ts);
    # dentro del mismo dÃ­a, prioridad kg-first.
    def _clave(it):
        dia = (it["ts"] or "")[:10] or f"{it['periodo'] or '0000-00'}-01"
        return (dia, it["prioridad"])

    items.sort(key=_clave, reverse=True)
    items = items[:int(limite)]
    return {"items": items, "total": len(items)}


def leer_materiales_normalizados_recientes(limite=10):
    """Top materiales por DescriptionNormalizada del mes actual, con cobertura
    visible. DeterminÃ­stico, solo lectura de la derivada. Con estado_confianza
    'debil' no debe usarse para conclusiones fuertes."""
    resultado = {
        "periodo": date.today().strftime("%Y-%m"),
        "disponible": False,
        "cobertura_pct": 0,
        "estado_confianza": None,
        "apto_para_conclusiones": False,
        "registros_total_periodo": 0,
        "registros_normalizados_periodo": 0,
        "pct_kilos_normalizados": 0,
        "top_materiales": [],
    }
    try:
        conn = get_ia_connection()
        if not conn:
            return resultado
        cur = conn.cursor()
        cur.execute(f"""
            SELECT description_normalizada, registros, kilos_total,
                   registros_total_periodo, registros_normalizados_periodo,
                   cobertura_pct_periodo, estado_confianza,
                   pct_kilos_normalizados_periodo, primer_movimiento, ultimo_movimiento
            FROM ia_resumen_mensual_description_normalizada
            WHERE periodo = %s AND criterio_version = %s
            ORDER BY kilos_total DESC
            LIMIT %s
        """, (resultado["periodo"], DERIVADAS_VERSION, int(limite)))
        filas = cur.fetchall() or []
        cur.close()
        conn.close()
        if not filas:
            return resultado
        f0 = filas[0]
        resultado.update({
            "disponible": True,
            "cobertura_pct": float(f0["cobertura_pct_periodo"] or 0),
            "estado_confianza": f0["estado_confianza"],
            "apto_para_conclusiones": f0["estado_confianza"] in ("fuerte", "parcial"),
            "registros_total_periodo": int(f0["registros_total_periodo"] or 0),
            "registros_normalizados_periodo": int(f0["registros_normalizados_periodo"] or 0),
            "pct_kilos_normalizados": float(f0["pct_kilos_normalizados_periodo"] or 0),
        })
        for f in filas:
            resultado["top_materiales"].append({
                "material": f["description_normalizada"],
                "registros": int(f["registros"] or 0),
                "kilos_total": float(f["kilos_total"] or 0),
                "primer_movimiento": str(f["primer_movimiento"]) if f["primer_movimiento"] else None,
                "ultimo_movimiento": str(f["ultimo_movimiento"]) if f["ultimo_movimiento"] else None,
            })
    except Exception as e:
        print(f"Error en leer_materiales_normalizados_recientes: {e}", file=sys.stderr)
    return resultado


def leer_compras_materiales_normalizados_recientes(limite=8):
    """Compras/precios por material normalizado del mes actual, con cobertura y
    alertas determinÃ­sticas simples. Solo lectura; sin moneda ni causa inferidas."""
    periodo = date.today().strftime("%Y-%m")
    resultado = {
        "periodo": periodo,
        "disponible": False,
        "cobertura_pct": 0,
        "estado_confianza": None,
        "apto_para_conclusiones": False,
        "top_materiales_por_kg": [],
        "top_proveedor_material": [],
        "top_monto_estimado": [],
        "alertas_deterministicas": [],
        "calidad_error_registro": {
            "kg_error_registro": 0,
            "registros_error_registro": 0,
            "materiales_afectados": [],
            "ejemplos_repetidos": [],
        },
    }
    try:
        conn = get_ia_connection()
        if not conn:
            return resultado
        cur = conn.cursor()

        # Ranking econÃ³mico: SOLO tipos comprables (ingresos); ERROR_REGISTRO,
        # PRODUCCION y despachos no entran en compras/precios
        cur.execute(f"""
            SELECT tipo_movimiento, material_normalizado, registros, kilos_total,
                   precio_registros, precio_promedio, precio_ponderado_kg, monto_estimado,
                   cobertura_pct_periodo, estado_confianza
            FROM ia_resumen_mensual_material_normalizado_tipo
            WHERE periodo = %s AND criterio_version = %s
              AND {_sql_tipo_compra_proveedor('tipo_movimiento')}
            ORDER BY kilos_total DESC
            LIMIT %s
        """, (periodo, DERIVADAS_VERSION, int(limite)))
        mat_tipo = cur.fetchall() or []

        # Calidad operativa: ERROR_REGISTRO por separado (tipo real de la planta;
        # se muestra material afectado, sin inferir proveedor ni precio)
        cur.execute(f"""
            SELECT material_normalizado, registros, kilos_total
            FROM ia_resumen_mensual_material_normalizado_tipo
            WHERE periodo = %s AND criterio_version = %s
              AND tipo_movimiento = 'ERROR_REGISTRO'
            ORDER BY kilos_total DESC
            LIMIT %s
        """, (periodo, DERIVADAS_VERSION, int(limite)))
        err_reg = cur.fetchall() or []

        cur.execute(f"""
            SELECT proveedor, material_normalizado, tipo_movimiento, registros, kilos_total,
                   precio_ponderado_kg, monto_estimado, pct_kilos_del_material,
                   pct_kilos_del_proveedor, estado_confianza
            FROM ia_resumen_mensual_proveedor_material_normalizado
            WHERE periodo = %s AND criterio_version = %s
            ORDER BY kilos_total DESC
            LIMIT %s
        """, (periodo, DERIVADAS_VERSION, int(limite)))
        prov_mat = cur.fetchall() or []

        cur.execute(f"""
            SELECT proveedor, material_normalizado, tipo_movimiento, kilos_total,
                   precio_ponderado_kg, monto_estimado
            FROM ia_resumen_mensual_proveedor_material_normalizado
            WHERE periodo = %s AND criterio_version = %s AND monto_estimado IS NOT NULL
            ORDER BY monto_estimado DESC
            LIMIT %s
        """, (periodo, DERIVADAS_VERSION, int(limite)))
        top_monto = cur.fetchall() or []

        # Materiales con historial normalizado previo (para alerta 'sin historial')
        cur.execute(f"""
            SELECT DISTINCT material_normalizado
            FROM ia_resumen_mensual_material_normalizado_tipo
            WHERE periodo < %s AND criterio_version = %s
        """, (periodo, DERIVADAS_VERSION))
        con_historial = {r["material_normalizado"] for r in (cur.fetchall() or [])}
        cur.close()
        conn.close()

        # Bloque de calidad operativa: ERROR_REGISTRO separado del anÃ¡lisis econÃ³mico
        calidad = resultado["calidad_error_registro"]
        for r in err_reg:
            kg_e = float(r["kilos_total"] or 0)
            calidad["kg_error_registro"] += kg_e
            calidad["registros_error_registro"] += int(r["registros"] or 0)
            calidad["materiales_afectados"].append({
                "material": r["material_normalizado"],
                "kilos_total": kg_e,
                "registros": int(r["registros"] or 0),
            })
        calidad["kg_error_registro"] = round(calidad["kg_error_registro"], 2)

        # Ejemplos repetidos (mismo FechaHora + kilos + DescriptionNormalizada)
        try:
            conn_op = get_db_connection()
            if conn_op:
                cur_op = conn_op.cursor()
                cur_op.execute("""
                    SELECT FechaHora, kilos, DescriptionNormalizada AS material,
                           COUNT(*) AS repeticiones
                    FROM TiposDeMovimiento
                    WHERE TiposDeMovimiento = 'ERROR_REGISTRO'
                      AND DATE_FORMAT(FechaHora, '%%Y-%%m') = %s
                    GROUP BY FechaHora, kilos, DescriptionNormalizada
                    HAVING COUNT(*) > 1
                    ORDER BY repeticiones DESC, FechaHora DESC
                    LIMIT 5
                """, (periodo,))
                for r in (cur_op.fetchall() or []):
                    calidad["ejemplos_repetidos"].append({
                        "fecha_hora": str(r["FechaHora"]) if r["FechaHora"] else None,
                        "kilos": float(r["kilos"] or 0),
                        "material": r["material"],
                        "repeticiones": int(r["repeticiones"] or 0),
                    })
                cur_op.close()
                conn_op.close()
        except Exception:
            pass

        # Alertas de calidad operativa (kg primero; sin causa inferida)
        alertas = resultado["alertas_deterministicas"]
        if ERROR_REGISTRO_ALERTAS_DETALLADAS and calidad["kg_error_registro"] >= ERROR_REGISTRO_KG_ALERTA:
            mats_txt = ", ".join(m["material"] for m in calidad["materiales_afectados"][:3]) or "sin material normalizado"
            alertas.append({
                "tipo": "error_registro_kg",
                "texto": (f"ERROR_REGISTRO: {int(calidad['kg_error_registro']):,} kg "
                          f"({calidad['registros_error_registro']} registros) en {periodo}. "
                          f"Materiales afectados: {mats_txt}."),
            })
        rep_max = max((e["repeticiones"] for e in calidad["ejemplos_repetidos"]), default=0)
        if ERROR_REGISTRO_ALERTAS_DETALLADAS and (rep_max >= 3 or len(calidad["ejemplos_repetidos"]) >= 3):
            e0 = calidad["ejemplos_repetidos"][0]
            alertas.append({
                "tipo": "error_registro_repetidos",
                "texto": (f"ERROR_REGISTRO con registros repetidos: {len(calidad['ejemplos_repetidos'])} grupos "
                          f"con misma FechaHora+kilos+material (mÃ¡x {rep_max} repeticiones; "
                          f"ej: {e0['material'] or '?'} {int(e0['kilos']):,} kg el {e0['fecha_hora']})."),
            })

        if not mat_tipo:
            resultado["disponible"] = bool(err_reg)
            return resultado

        def _f(v):
            return float(v) if v is not None else None

        resultado["disponible"] = True
        resultado["cobertura_pct"] = _f(mat_tipo[0]["cobertura_pct_periodo"]) or 0
        resultado["estado_confianza"] = mat_tipo[0]["estado_confianza"]
        resultado["apto_para_conclusiones"] = mat_tipo[0]["estado_confianza"] in ("fuerte", "parcial")

        # Cada item lleva material_normalizado (clave canÃ³nica) y material (alias
        # para el dashboard); mismo valor en ambas.
        for r in mat_tipo:
            resultado["top_materiales_por_kg"].append({
                "material_normalizado": r["material_normalizado"],
                "material": r["material_normalizado"], "tipo_movimiento": r["tipo_movimiento"],
                "registros": int(r["registros"] or 0), "kilos_total": _f(r["kilos_total"]) or 0,
                "precio_ponderado_kg": _f(r["precio_ponderado_kg"]),
                "monto_estimado": _f(r["monto_estimado"]),
                "estado_confianza": r["estado_confianza"],
            })
        for r in prov_mat:
            resultado["top_proveedor_material"].append({
                "proveedor": r["proveedor"],
                "material_normalizado": r["material_normalizado"],
                "material": r["material_normalizado"],
                "tipo_movimiento": r["tipo_movimiento"],
                "kilos_total": _f(r["kilos_total"]) or 0,
                "precio_ponderado_kg": _f(r["precio_ponderado_kg"]),
                "monto_estimado": _f(r["monto_estimado"]),
                "pct_kilos_del_material": _f(r["pct_kilos_del_material"]) or 0,
            })
        for r in top_monto:
            resultado["top_monto_estimado"].append({
                "proveedor": r["proveedor"],
                "material_normalizado": r["material_normalizado"],
                "material": r["material_normalizado"],
                "tipo_movimiento": r["tipo_movimiento"],
                "kilos_total": _f(r["kilos_total"]) or 0,
                "precio_ponderado_kg": _f(r["precio_ponderado_kg"]),
                "monto_estimado": _f(r["monto_estimado"]) or 0,
            })

        # Alertas determinÃ­sticas simples (kg primero, sin causa inferida)
        alertas = resultado["alertas_deterministicas"]
        for m in resultado["top_materiales_por_kg"][:5]:
            if m["kilos_total"] > 0 and not m["precio_ponderado_kg"]:
                alertas.append({
                    "tipo": "precio_ponderado_faltante",
                    "texto": (f"{m['material']} ({m['tipo_movimiento']}): "
                              f"{int(m['kilos_total']):,} kg sin precio ponderado (sin filas con Precio > 0)."),
                })
            if m["estado_confianza"] == "fuerte" and m["material"] not in con_historial:
                alertas.append({
                    "tipo": "material_fuerte_sin_historial",
                    "texto": (f"{m['material']}: {int(m['kilos_total']):,} kg este mes; "
                              "sin historial normalizado en meses previos."),
                })
        for pm in resultado["top_proveedor_material"][:5]:
            if pm["pct_kilos_del_material"] >= 80 and pm["kilos_total"] >= 500:
                alertas.append({
                    "tipo": "proveedor_material_concentrado",
                    "texto": (f"{pm['proveedor']} concentra {pm['pct_kilos_del_material']}% de "
                              f"{pm['material']} ({int(pm['kilos_total']):,} kg en {pm['tipo_movimiento']})."),
                })
    except Exception as e:
        print(f"Error en leer_compras_materiales_normalizados_recientes: {e}", file=sys.stderr)
    return resultado


def leer_calidad_error_registro(limite=8):
    """Bloque de calidad de dato: ERROR_REGISTRO del mes actual, por material
    normalizado y con conteo de filas sin proveedor. Solo lectura de la base
    operativa; no infiere proveedor ni precio; fuera de rankings econÃ³micos."""
    periodo = date.today().strftime("%Y-%m")
    resultado = {
        "periodo": periodo,
        "registros": 0,
        "kilos_total": 0,
        "sin_proveedor": 0,
        "top_materiales": [],
    }
    try:
        conn = get_db_connection()
        if not conn:
            return resultado
        cur = conn.cursor()
        cur.execute(f"""
            SELECT DescriptionNormalizada AS material_normalizado,
                   COUNT(*) AS registros,
                   COALESCE(SUM(kilos), 0) AS kilos,
                   SUM(CASE WHEN Proveedor IS NULL OR TRIM(Proveedor) = '' THEN 1 ELSE 0 END) AS sin_proveedor
            FROM TiposDeMovimiento
            WHERE TiposDeMovimiento = 'ERROR_REGISTRO'
              AND DATE_FORMAT(FechaHora, '%%Y-%%m') = %s
            GROUP BY DescriptionNormalizada
            ORDER BY kilos DESC
        """, (periodo,))
        filas = cur.fetchall() or []
        cur.close()
        conn.close()
        for r in filas:
            registros = int(r["registros"] or 0)
            kilos = float(r["kilos"] or 0)
            sin_prov = int(r["sin_proveedor"] or 0)
            resultado["registros"] += registros
            resultado["kilos_total"] += kilos
            resultado["sin_proveedor"] += sin_prov
            if len(resultado["top_materiales"]) < int(limite):
                resultado["top_materiales"].append({
                    "material_normalizado": r["material_normalizado"],
                    "registros": registros,
                    "kilos": round(kilos, 2),
                    "sin_proveedor": sin_prov,
                })
        resultado["kilos_total"] = round(resultado["kilos_total"], 2)
    except Exception as e:
        print(f"Error en leer_calidad_error_registro: {e}", file=sys.stderr)
    return resultado


# 0 = todos los meses pintados (los datos pesan ~1.5 KB por mes)
MESES_PINTADOS_MAX = int(os.environ.get("MESES_PINTADOS_MAX", "0"))


def leer_meses_pintados(max_meses=None, max_tipos=8, max_materiales=3):
    """Vista por mes 'pintado' (con derivadas calculadas), de reciente a antiguo:
    tipos de movimiento del mes con kg/registros, y resumen de compras
    normalizadas del mes si la dimensiÃ³n existe. DeterminÃ­stico, solo lectura,
    3 queries totales sin importar la cantidad de meses (0 = todos)."""
    if max_meses is None:
        max_meses = MESES_PINTADOS_MAX
    resultado = {"meses": []}
    try:
        conn = get_ia_connection()
        if not conn:
            return resultado
        cur = conn.cursor()
        cur.execute(f"""
            SELECT periodo, estado_periodo
            FROM ia_periodos_procesados
            WHERE criterio_version = %s
            ORDER BY periodo DESC
        """, (DERIVADAS_VERSION,))
        periodos = cur.fetchall() or []
        if max_meses and int(max_meses) > 0:
            periodos = periodos[:int(max_meses)]
        periodos_set = {p["periodo"] for p in periodos}

        # Tipos de movimiento de TODOS los meses en una sola query
        tipos_por_mes = {}
        cur.execute(f"""
            SELECT periodo, TiposDeMovimiento AS tipo, registros, kilos_total
            FROM ia_resumen_mensual_tipo_movimiento
            WHERE criterio_version = %s
            ORDER BY periodo DESC, kilos_total DESC
        """, (DERIVADAS_VERSION,))
        for t in (cur.fetchall() or []):
            if t["periodo"] not in periodos_set:
                continue
            lista = tipos_por_mes.setdefault(t["periodo"], [])
            if len(lista) >= int(max_tipos):
                continue
            lista.append({
                "tipo": t["tipo"],
                "kg": round(float(t["kilos_total"] or 0), 2),
                "registros": int(t["registros"] or 0),
                "comprable": _tipo_es_comprable(t["tipo"]),
            })

        # Compras normalizadas de TODOS los meses en una sola query
        compras_por_mes = {}
        try:
            cur.execute(f"""
                SELECT periodo, material_normalizado AS material,
                       SUM(kilos_total) AS kg,
                       SUM(COALESCE(monto_estimado, 0)) AS monto,
                       MAX(cobertura_pct_periodo) AS cobertura
                FROM ia_resumen_mensual_material_normalizado_tipo
                WHERE criterio_version = %s
                  AND {_sql_tipo_compra_proveedor('tipo_movimiento')}
                GROUP BY periodo, material_normalizado
                ORDER BY periodo DESC, kg DESC
            """, (DERIVADAS_VERSION,))
            for f in (cur.fetchall() or []):
                if f["periodo"] not in periodos_set:
                    continue
                c = compras_por_mes.setdefault(f["periodo"], {"cobertura": 0.0, "materiales": [], "proveedores": [], "pares": []})
                c["cobertura"] = max(c["cobertura"], float(f["cobertura"] or 0))
                if len(c["materiales"]) < int(max_materiales):
                    c["materiales"].append({
                        "material": f["material"],
                        "kg": round(float(f["kg"] or 0), 2),
                        "monto_estimado": round(float(f["monto"] or 0), 2) or None,
                    })
            cur.execute(f"""
                SELECT periodo,
                       COALESCE(NULLIF(TRIM(proveedor), ''), 'sin proveedor') AS proveedor,
                       SUM(kilos_total) AS kg,
                       SUM(registros) AS registros,
                       SUM(COALESCE(monto_estimado, 0)) AS monto,
                       MAX(cobertura_pct_periodo) AS cobertura
                FROM ia_resumen_mensual_proveedor_material_normalizado
                WHERE criterio_version = %s
                  AND {_sql_tipo_compra_proveedor('tipo_movimiento')}
                GROUP BY periodo, proveedor
                ORDER BY periodo DESC, kg DESC
            """, (DERIVADAS_VERSION,))
            for f in (cur.fetchall() or []):
                if f["periodo"] not in periodos_set:
                    continue
                c = compras_por_mes.setdefault(f["periodo"], {"cobertura": 0.0, "materiales": [], "proveedores": [], "pares": []})
                c["cobertura"] = max(c["cobertura"], float(f["cobertura"] or 0))
                if len(c["proveedores"]) < 8:
                    c["proveedores"].append({
                        "proveedor": f["proveedor"],
                        "kg": round(float(f["kg"] or 0), 2),
                        "registros": int(f["registros"] or 0),
                        "monto_estimado": round(float(f["monto"] or 0), 2) or None,
                    })

            cur.execute(f"""
                SELECT periodo,
                       COALESCE(NULLIF(TRIM(proveedor), ''), 'sin proveedor') AS proveedor,
                       material_normalizado AS material,
                       SUM(kilos_total) AS kg,
                       SUM(registros) AS registros,
                       SUM(COALESCE(monto_estimado, 0)) AS monto,
                       MAX(precio_ponderado_kg) AS precio_ponderado_kg,
                       MAX(cobertura_pct_periodo) AS cobertura
                FROM ia_resumen_mensual_proveedor_material_normalizado
                WHERE criterio_version = %s
                  AND {_sql_tipo_compra_proveedor('tipo_movimiento')}
                GROUP BY periodo, proveedor, material_normalizado
                ORDER BY periodo DESC, kg DESC
            """, (DERIVADAS_VERSION,))
            for f in (cur.fetchall() or []):
                if f["periodo"] not in periodos_set:
                    continue
                c = compras_por_mes.setdefault(f["periodo"], {"cobertura": 0.0, "materiales": [], "proveedores": [], "pares": []})
                c["cobertura"] = max(c["cobertura"], float(f["cobertura"] or 0))
                if len(c["pares"]) < 12:
                    c["pares"].append({
                        "proveedor": f["proveedor"],
                        "material": f["material"],
                        "kg": round(float(f["kg"] or 0), 2),
                        "registros": int(f["registros"] or 0),
                        "monto_estimado": round(float(f["monto"] or 0), 2) or None,
                        "precio_ponderado_kg": round(float(f["precio_ponderado_kg"] or 0), 4) if f["precio_ponderado_kg"] is not None else None,
                    })
        except Exception:
            compras_por_mes = {}

        # Produccion abierta: descompone la barra PRODUCCION por maquina,
        # operador y material normalizado, sin mezclar con compras/despachos.
        produccion_por_mes = {}
        detalles_maquina_por_mes = {}
        try:
            cur.execute(f"""
                SELECT periodo, Maquina AS nombre, registros, kilos_total AS kg
                FROM ia_resumen_mensual_produccion_maquina
                WHERE criterio_version = %s
                ORDER BY periodo DESC, kilos_total DESC
            """, (DERIVADAS_VERSION,))
            for r in (cur.fetchall() or []):
                if r["periodo"] not in periodos_set:
                    continue
                pprod = produccion_por_mes.setdefault(r["periodo"], {"maquinas": [], "operadores": [], "materiales": [], "cobertura_material_pct": 0.0})
                if len(pprod["maquinas"]) < 12:
                    pprod["maquinas"].append({
                        "nombre": r["nombre"],
                        "kg": round(float(r["kg"] or 0), 2),
                        "registros": int(r["registros"] or 0),
                    })

            cur.execute(f"""
                SELECT periodo, Operador AS nombre, registros, kilos_total AS kg
                FROM ia_resumen_mensual_operador_tipo
                WHERE criterio_version = %s AND UPPER(TRIM(tipo_movimiento)) = 'PRODUCCION'
                ORDER BY periodo DESC, kilos_total DESC
            """, (DERIVADAS_VERSION,))
            for r in (cur.fetchall() or []):
                if r["periodo"] not in periodos_set:
                    continue
                pprod = produccion_por_mes.setdefault(r["periodo"], {"maquinas": [], "operadores": [], "materiales": [], "cobertura_material_pct": 0.0})
                if len(pprod["operadores"]) < 12:
                    pprod["operadores"].append({
                        "nombre": r["nombre"],
                        "kg": round(float(r["kg"] or 0), 2),
                        "registros": int(r["registros"] or 0),
                    })

            cur.execute(f"""
                SELECT periodo, material_normalizado AS nombre,
                       SUM(registros) AS registros,
                       SUM(kilos_total) AS kg,
                       MAX(cobertura_pct_periodo) AS cobertura
                FROM ia_resumen_mensual_material_normalizado_tipo
                WHERE criterio_version = %s AND UPPER(TRIM(tipo_movimiento)) = 'PRODUCCION'
                GROUP BY periodo, material_normalizado
                ORDER BY periodo DESC, kg DESC
            """, (DERIVADAS_VERSION,))
            for r in (cur.fetchall() or []):
                if r["periodo"] not in periodos_set:
                    continue
                pprod = produccion_por_mes.setdefault(r["periodo"], {"maquinas": [], "operadores": [], "materiales": [], "cobertura_material_pct": 0.0})
                pprod["cobertura_material_pct"] = max(pprod["cobertura_material_pct"], float(r["cobertura"] or 0))
                if len(pprod["materiales"]) < 12:
                    pprod["materiales"].append({
                        "nombre": r["nombre"],
                        "kg": round(float(r["kg"] or 0), 2),
                        "registros": int(r["registros"] or 0),
                    })

            # Cruce historico por maquina: dentro de cada maquina, que operadores
            # y que materiales explican la barra de PRODUCCION de ese mes.
            if periodos_set:
                conn_op = None
                cur_op = None
                try:
                    periodos_ordenados = sorted(str(p) for p in periodos_set if p)
                    p_ini = periodos_ordenados[0]
                    p_fin = periodos_ordenados[-1]
                    yr_fin, mo_fin = int(p_fin[:4]), int(p_fin[5:7])
                    inicio_hist = f"{p_ini}-01"
                    fin_hist = (date(yr_fin + (1 if mo_fin == 12 else 0), 1 if mo_fin == 12 else mo_fin + 1, 1)).strftime("%Y-%m-%d")
                    conn_op = get_db_connection()
                    if conn_op:
                        cur_op = conn_op.cursor()
                        cur_op.execute("""
                            SELECT DATE_FORMAT(FechaHora, '%%Y-%%m') AS periodo,
                                   Maquina,
                                   Operador,
                                   COUNT(*) AS registros,
                                   COALESCE(SUM(kilos), 0) AS kg
                            FROM TiposDeMovimiento
                            WHERE FechaHora >= %s AND FechaHora < %s
                              AND TiposDeMovimiento = 'PRODUCCION'
                              AND Maquina IS NOT NULL AND TRIM(Maquina) <> ''
                              AND Operador IS NOT NULL AND TRIM(Operador) <> ''
                            GROUP BY periodo, Maquina, Operador
                            ORDER BY periodo DESC, Maquina, kg DESC
                        """, (inicio_hist, fin_hist))
                        for x in (cur_op.fetchall() or []):
                            periodo_x = str(x.get("periodo") or "")
                            maquina_x = str(x.get("Maquina") or "").strip()
                            operador_x = str(x.get("Operador") or "").strip()
                            if periodo_x not in periodos_set or not maquina_x or not operador_x:
                                continue
                            det = detalles_maquina_por_mes.setdefault(periodo_x, {}).setdefault(maquina_x.lower(), {"operadores": [], "materiales": []})
                            if len(det["operadores"]) < 12:
                                det["operadores"].append({
                                    "nombre": operador_x,
                                    "kg": round(float(x.get("kg") or 0), 2),
                                    "registros": int(x.get("registros") or 0),
                                })

                        cur_op.execute("SHOW COLUMNS FROM TiposDeMovimiento LIKE 'DescriptionNormalizada'")
                        tiene_desc_norm = bool(cur_op.fetchone())
                        material_expr = ("COALESCE(NULLIF(TRIM(DescriptionNormalizada), ''), "
                                         "NULLIF(TRIM(Description), ''), NULLIF(TRIM(Materiales), ''))") if tiene_desc_norm else \
                                        "COALESCE(NULLIF(TRIM(Description), ''), NULLIF(TRIM(Materiales), ''))"
                        cur_op.execute(f"""
                            SELECT DATE_FORMAT(FechaHora, '%%Y-%%m') AS periodo,
                                   Maquina,
                                   {material_expr} AS material,
                                   COUNT(*) AS registros,
                                   COALESCE(SUM(kilos), 0) AS kg
                            FROM TiposDeMovimiento
                            WHERE FechaHora >= %s AND FechaHora < %s
                              AND TiposDeMovimiento = 'PRODUCCION'
                              AND Maquina IS NOT NULL AND TRIM(Maquina) <> ''
                            GROUP BY periodo, Maquina, material
                            HAVING material IS NOT NULL AND material <> ''
                            ORDER BY periodo DESC, Maquina, kg DESC
                        """, (inicio_hist, fin_hist))
                        for x in (cur_op.fetchall() or []):
                            periodo_x = str(x.get("periodo") or "")
                            maquina_x = str(x.get("Maquina") or "").strip()
                            material_x = str(x.get("material") or "").strip()
                            if periodo_x not in periodos_set or not maquina_x or not material_x:
                                continue
                            det = detalles_maquina_por_mes.setdefault(periodo_x, {}).setdefault(maquina_x.lower(), {"operadores": [], "materiales": []})
                            if len(det["materiales"]) < 12:
                                det["materiales"].append({
                                    "nombre": material_x,
                                    "kg": round(float(x.get("kg") or 0), 2),
                                    "registros": int(x.get("registros") or 0),
                                })
                except Exception as e_det_prod:
                    print(f"Error en leer_meses_pintados detalle_maquina_produccion: {e_det_prod}", file=sys.stderr)
                    detalles_maquina_por_mes = {}
                finally:
                    try:
                        if cur_op:
                            cur_op.close()
                        if conn_op:
                            conn_op.close()
                    except Exception:
                        pass

            for periodo_x, maquinas_det in detalles_maquina_por_mes.items():
                pprod = produccion_por_mes.get(periodo_x)
                if not pprod:
                    continue
                for maq in pprod.get("maquinas", []):
                    clave_maq = str(maq.get("nombre") or "").strip().lower()
                    det = maquinas_det.get(clave_maq)
                    if det:
                        maq["operadores"] = det.get("operadores", [])[:12]
                        maq["materiales"] = det.get("materiales", [])[:12]
        except Exception:
            produccion_por_mes = {}

        # Despacho_PT depurado: no todo despacho PT es venta comercial sana.
        # Los fardos/limpieza/liberacion de predio se muestran aparte y los
        # formatos dudosos quedan en revisar; ningun kg desaparece.
        despacho_pt_por_mes = {}
        try:
            cur.execute(f"""
                SELECT periodo, material_normalizado AS material,
                       SUM(registros) AS registros,
                       SUM(kilos_total) AS kg,
                       SUM(precio_registros) AS precio_registros,
                       MAX(precio_ponderado_kg) AS precio_ponderado_kg,
                       MAX(cobertura_pct_periodo) AS cobertura
                FROM ia_resumen_mensual_material_normalizado_tipo
                WHERE criterio_version = %s
                  AND UPPER(TRIM(tipo_movimiento)) = 'DESPACHO_PT'
                GROUP BY periodo, material_normalizado
                ORDER BY periodo DESC, kg DESC
            """, (DERIVADAS_VERSION,))
            for r in (cur.fetchall() or []):
                if r["periodo"] not in periodos_set:
                    continue
                bucket_key, motivo = clasificar_despacho_pt(r.get("material"), r.get("precio_ponderado_kg"))
                d = despacho_pt_por_mes.setdefault(r["periodo"], {
                    "tipo_movimiento": "Despacho_PT",
                    "criterio": "comercial si DescriptionNormalizada contiene PELLETIZADO/PULVERIZADO/MICRONIZADO/EXTRUDADO",
                    "precio_bajo_umbral": DESPACHO_PRECIO_BAJO_UMBRAL,
                    "total_kg": 0.0,
                    "total_registros": 0,
                    "cobertura_material_pct": 0.0,
                    "clientes": [],
                    "comercial_normal": {"kg": 0.0, "registros": 0, "items": []},
                    "especial_limpieza": {"kg": 0.0, "registros": 0, "items": []},
                    "revisar": {"kg": 0.0, "registros": 0, "items": []},
                })
                kg = round(float(r.get("kg") or 0), 2)
                regs = int(r.get("registros") or 0)
                d["total_kg"] += kg
                d["total_registros"] += regs
                d["cobertura_material_pct"] = max(d["cobertura_material_pct"], float(r.get("cobertura") or 0))
                b = d[bucket_key]
                b["kg"] += kg
                b["registros"] += regs
                if len(b["items"]) < 8:
                    b["items"].append({
                        "material": r.get("material") or "sin DescriptionNormalizada",
                        "kg": kg,
                        "registros": regs,
                        "categoria": bucket_key,
                        "motivo": motivo,
                        "precio_ponderado_kg": round(float(r.get("precio_ponderado_kg") or 0), 4) if r.get("precio_ponderado_kg") is not None else None,
                    })
            # Cliente/destino del despacho: en TiposDeMovimiento la columna
            # Proveedor funciona como entidad asociada al despacho, no como
            # proveedor de compra. Se consulta la base operativa.
            conn_op_cli = None
            cur_op_cli = None
            try:
                p_min, p_max = min(periodos_set), max(periodos_set)
                mo_max = int(p_max[5:7])
                fin_cli = date(int(p_max[:4]) + (1 if mo_max == 12 else 0), 1 if mo_max == 12 else mo_max + 1, 1).strftime("%Y-%m-%d")
                conn_op_cli = get_db_connection()
                if conn_op_cli:
                    cur_op_cli = conn_op_cli.cursor()
                    cur_op_cli.execute("""
                        SELECT DATE_FORMAT(FechaHora, '%%Y-%%m') AS periodo,
                               COALESCE(NULLIF(TRIM(Proveedor), ''), 'sin cliente/destino') AS cliente,
                               COUNT(*) AS registros,
                               COALESCE(SUM(kilos), 0) AS kg
                        FROM TiposDeMovimiento
                        WHERE FechaHora >= %s AND FechaHora < %s
                          AND UPPER(TRIM(TiposDeMovimiento)) = 'DESPACHO_PT'
                        GROUP BY periodo, cliente
                        ORDER BY periodo DESC, kg DESC
                    """, (f"{p_min}-01", fin_cli))
                    for rcli in (cur_op_cli.fetchall() or []):
                        periodo_cli = str(rcli.get("periodo") or "")
                        if periodo_cli not in periodos_set or periodo_cli not in despacho_pt_por_mes:
                            continue
                        d = despacho_pt_por_mes[periodo_cli]
                        if len(d["clientes"]) < 8:
                            kg_cli = round(float(rcli.get("kg") or 0), 2)
                            d["clientes"].append({
                                "cliente": rcli.get("cliente"),
                                "kg": kg_cli,
                                "registros": int(rcli.get("registros") or 0),
                            })

                    cur_op_cli.execute("SHOW COLUMNS FROM TiposDeMovimiento LIKE 'DescriptionNormalizada'")
                    tiene_desc_norm_cli = bool(cur_op_cli.fetchone())
                    material_expr_cli = ("COALESCE(NULLIF(TRIM(DescriptionNormalizada), ''), "
                                         "NULLIF(TRIM(Description), ''), NULLIF(TRIM(Materiales), ''))") if tiene_desc_norm_cli else \
                                        "COALESCE(NULLIF(TRIM(Description), ''), NULLIF(TRIM(Materiales), ''))"
                    cur_op_cli.execute(f"""
                        SELECT DATE_FORMAT(FechaHora, '%%Y-%%m') AS periodo,
                               COALESCE(NULLIF(TRIM(Proveedor), ''), 'sin cliente/destino') AS cliente,
                               {material_expr_cli} AS material,
                               COUNT(*) AS registros,
                               COALESCE(SUM(kilos), 0) AS kg,
                               CASE WHEN SUM(CASE WHEN Precio IS NOT NULL AND Precio > 0 AND kilos > 0 THEN kilos ELSE 0 END) > 0
                                    THEN SUM(CASE WHEN Precio IS NOT NULL AND Precio > 0 AND kilos > 0 THEN Precio * kilos ELSE 0 END) /
                                         SUM(CASE WHEN Precio IS NOT NULL AND Precio > 0 AND kilos > 0 THEN kilos ELSE 0 END)
                                    ELSE NULL END AS precio_ponderado_kg
                        FROM TiposDeMovimiento
                        WHERE FechaHora >= %s AND FechaHora < %s
                          AND UPPER(TRIM(TiposDeMovimiento)) = 'DESPACHO_PT'
                        GROUP BY periodo, cliente, material
                        HAVING material IS NOT NULL AND material <> ''
                        ORDER BY periodo DESC, cliente, kg DESC
                    """, (f"{p_min}-01", fin_cli))
                    cliente_materiales_comercial = {}
                    for rcm in (cur_op_cli.fetchall() or []):
                        periodo_cm = str(rcm.get("periodo") or "")
                        if periodo_cm not in periodos_set or periodo_cm not in despacho_pt_por_mes:
                            continue
                        bucket_key_cm, _motivo_cm = clasificar_despacho_pt(rcm.get("material"), rcm.get("precio_ponderado_kg"))
                        if bucket_key_cm != "comercial_normal":
                            continue
                        cliente_cm = str(rcm.get("cliente") or "sin cliente/destino").strip() or "sin cliente/destino"
                        kg_cm = round(float(rcm.get("kg") or 0), 2)
                        cli = cliente_materiales_comercial.setdefault(periodo_cm, {}).setdefault(cliente_cm, {
                            "cliente": cliente_cm,
                            "kg": 0.0,
                            "registros": 0,
                            "materiales": [],
                        })
                        cli["kg"] += kg_cm
                        cli["registros"] += int(rcm.get("registros") or 0)
                        if len(cli["materiales"]) < 8:
                            cli["materiales"].append({
                                "material": rcm.get("material"),
                                "kg": kg_cm,
                                "registros": int(rcm.get("registros") or 0),
                                "precio_ponderado_kg": round(float(rcm.get("precio_ponderado_kg") or 0), 4) if rcm.get("precio_ponderado_kg") is not None else None,
                            })
                    for periodo_cm, clientes_map in cliente_materiales_comercial.items():
                        d = despacho_pt_por_mes.get(periodo_cm)
                        if not d:
                            continue
                        clientes_lista = sorted(clientes_map.values(), key=lambda x: x.get("kg") or 0, reverse=True)[:6]
                        for cli in clientes_lista:
                            cli["kg"] = round(float(cli.get("kg") or 0), 2)
                            cli["materiales"] = sorted(cli.get("materiales", []), key=lambda x: x.get("kg") or 0, reverse=True)[:6]
                        d["comercial_normal"]["clientes"] = clientes_lista
            except Exception as e_cli:
                print(f"Error en leer_meses_pintados despacho_pt_clientes: {e_cli}", file=sys.stderr)
            finally:
                try:
                    if cur_op_cli:
                        cur_op_cli.close()
                    if conn_op_cli:
                        conn_op_cli.close()
                except Exception:
                    pass

            for d in despacho_pt_por_mes.values():
                d["total_kg"] = round(d["total_kg"], 2)
                d["cobertura_material_pct"] = round(d["cobertura_material_pct"], 1)
                for k in ("comercial_normal", "especial_limpieza", "revisar"):
                    d[k]["kg"] = round(d[k]["kg"], 2)
                    d[k]["pct_del_total"] = round(d[k]["kg"] / d["total_kg"] * 100, 1) if d["total_kg"] > 0 else 0
        except Exception as e_desp:
            print(f"Error en leer_meses_pintados despacho_pt_depurado: {e_desp}", file=sys.stderr)
            despacho_pt_por_mes = {}
        cur.close()
        conn.close()

        for p in periodos:
            periodo = p["periodo"]
            tipos = tipos_por_mes.get(periodo, [])
            kg_total = sum(t["kg"] for t in tipos)
            for t in tipos:
                t["pct_kg"] = round(t["kg"] / kg_total * 100, 1) if kg_total > 0 else 0
            compras = None
            c = compras_por_mes.get(periodo)
            if c and c["materiales"]:
                cob = c["cobertura"]
                compras = {
                    "cobertura_pct": round(cob, 1),
                    "estado_confianza": ("fuerte" if cob >= 90
                                         else "parcial" if cob >= 30 else "debil"),
                    "top_materiales": c.get("materiales", []),
                    "top_proveedores": c.get("proveedores", []),
                    "top_proveedor_material": c.get("pares", []),
                }
            resultado["meses"].append({
                "periodo": periodo,
                "nombre": _nombre_mes_es(periodo),
                "estado_periodo": p["estado_periodo"],
                "kg_total": round(kg_total, 2),
                "tipos": tipos,
                "compras_normalizadas": compras,
                "produccion_abierta": produccion_por_mes.get(periodo),
                "despacho_pt_depurado": despacho_pt_por_mes.get(periodo),
            })
    except Exception as e:
        print(f"Error en leer_meses_pintados: {e}", file=sys.stderr)
    return resultado


def leer_mapa_historico_proveedores(max_proveedores=60, max_meses=33):
    """Matriz proveedores x meses para el dashboard, determinÃ­stica y sin Ollama.
    Filas: proveedores descubiertos por ia_fichas_operativas / ia_cola_curiosidad,
    priorizados por kg total histÃ³rico, meses con actividad y prioridad_score.
    Columnas: meses de ia_periodos_procesados (reciente -> antiguo).
    Celdas: kg, pct del mes, ranking (top1/top3/top10), ficha de ranking
    completada y tarea pendiente para ese proveedor/mes."""
    resultado = {
        "meses": [], "proveedores": [], "totales_mes": {},
        "resumen": {"proveedores_mostrados": 0, "meses_mostrados": 0,
                    "fichas_completadas": 0, "pendientes": 0},
    }
    try:
        conn = get_ia_connection()
        if not conn:
            return resultado
        cur = conn.cursor()

        # 1. Meses (reciente -> antiguo)
        cur.execute(f"""
            SELECT periodo FROM ia_periodos_procesados
            WHERE criterio_version = %s
            ORDER BY periodo DESC
            LIMIT %s
        """, (DERIVADAS_VERSION, int(max_meses)))
        meses = [r["periodo"] for r in (cur.fetchall() or [])]
        if not meses:
            cur.close()
            conn.close()
            return resultado
        resultado["meses"] = meses
        meses_set = set(meses)

        # Canonizar por alias: variantes crudas suman bajo el proveedor canÃ³nico
        mapa_alias_m, _inv_m = cargar_alias_proveedores(cur)

        # 2. Resumen mensual de ingresos por proveedor para esos meses
        marcadores = ", ".join(["%s"] * len(meses))
        cur.execute(f"""
            SELECT periodo, Proveedor, kilos_total
            FROM ia_resumen_mensual_ingresos_proveedor
            WHERE criterio_version = %s AND periodo IN ({marcadores})
        """, tuple([DERIVADAS_VERSION] + meses))
        kg_por_prov_mes = {}
        kg_mes_prov = {}
        for r in (cur.fetchall() or []):
            prov = canonizar_proveedor(r["Proveedor"], mapa_alias_m)
            per, kg = r["periodo"], float(r["kilos_total"] or 0)
            if not prov:
                continue
            kg_por_prov_mes[(prov, per)] = kg_por_prov_mes.get((prov, per), 0) + kg
            kg_mes_prov.setdefault(per, {})
            kg_mes_prov[per][prov] = kg_mes_prov[per].get(prov, 0) + kg
        rank_por_prov_mes = {}
        for per, d in kg_mes_prov.items():
            lista = sorted(d.items(), key=lambda x: (-x[1], x[0]))
            resultado["totales_mes"][per] = round(sum(kg for _, kg in lista), 2)
            for pos, (prov, _kg) in enumerate(lista, start=1):
                rank_por_prov_mes[(prov, per)] = pos

        # 3. Proveedores descubiertos por cola y fichas + indicadores
        def _prov_de(fila):
            if fila.get("tipo_nodo") == "proveedor_material":
                return canonizar_proveedor(fila.get("entidad_2"), mapa_alias_m)
            if fila.get("tipo_nodo") in ("material", "maquina", "operador"):
                return None
            return canonizar_proveedor(fila.get("entidad"), mapa_alias_m)

        descubiertos = {}
        pendientes_prov_mes = set()
        total_pendientes = 0
        cur.execute(f"""
            SELECT tipo_nodo, entidad, entidad_2, periodo, estado, prioridad_score
            FROM ia_cola_curiosidad
        """)
        for r in (cur.fetchall() or []):
            if r.get("estado") == "pendiente":
                total_pendientes += 1
            prov = _prov_de(r)
            if not prov:
                continue
            score = float(r.get("prioridad_score") or 0)
            if score > descubiertos.get(prov, 0) or prov not in descubiertos:
                descubiertos[prov] = max(descubiertos.get(prov, 0), score)
            if r.get("estado") == "pendiente" and r.get("periodo") in meses_set:
                pendientes_prov_mes.add((prov, r["periodo"]))

        fichas_ranking_prov_mes = set()
        fichas_por_prov = {}
        cur.execute(f"""
            SELECT tipo_tarea, tipo_nodo, entidad, entidad_2, periodo
            FROM ia_fichas_operativas
        """)
        for r in (cur.fetchall() or []):
            prov = _prov_de(r)
            if not prov:
                continue
            descubiertos.setdefault(prov, 0)
            fichas_por_prov[prov] = fichas_por_prov.get(prov, 0) + 1
            if r.get("tipo_tarea") == "ranking_vecinos_proveedor_mes" and r.get("periodo") in meses_set:
                fichas_ranking_prov_mes.add((prov, r["periodo"]))
        cur.close()
        conn.close()

        # 4. Priorizar filas: kg total histÃ³rico, meses activos, prioridad_score
        candidatos = []
        for prov, score in descubiertos.items():
            kg_total = sum(kg_por_prov_mes.get((prov, m), 0) for m in meses)
            meses_activos = sum(1 for m in meses if kg_por_prov_mes.get((prov, m), 0) > 0)
            candidatos.append((prov, kg_total, meses_activos, score))
        candidatos.sort(key=lambda x: (-x[1], -x[2], -x[3], x[0]))
        candidatos = candidatos[:int(max_proveedores)]

        fichas_mostradas = 0
        for prov, kg_total, meses_activos, score in candidatos:
            celdas = {}
            for m in meses:
                kg = kg_por_prov_mes.get((prov, m), 0)
                tiene_ficha = (prov, m) in fichas_ranking_prov_mes
                tiene_pendiente = (prov, m) in pendientes_prov_mes
                if kg <= 0 and not tiene_ficha and not tiene_pendiente:
                    continue  # celda vacÃ­a: no viaja en el JSON
                total_mes = resultado["totales_mes"].get(m, 0)
                rank = rank_por_prov_mes.get((prov, m))
                celdas[m] = {
                    "kg": round(kg, 2),
                    "pct": round(kg / total_mes * 100, 2) if total_mes > 0 and kg > 0 else 0,
                    "rank": rank,
                    "top": ("top1" if rank == 1 else "top3" if rank and rank <= 3
                            else "top10" if rank and rank <= 10 else None),
                    "ficha_ranking": tiene_ficha,
                    "pendiente": tiene_pendiente,
                }
            fichas_mostradas += fichas_por_prov.get(prov, 0)
            resultado["proveedores"].append({
                "proveedor": prov,
                "kg_total": round(kg_total, 2),
                "meses_activos": meses_activos,
                "prioridad": round(score, 4),
                "celdas": celdas,
            })

        resultado["resumen"] = {
            "proveedores_mostrados": len(resultado["proveedores"]),
            "meses_mostrados": len(meses),
            "fichas_completadas": fichas_mostradas,
            "pendientes": total_pendientes,
        }
    except Exception as e:
        print(f"Error en leer_mapa_historico_proveedores: {e}", file=sys.stderr)
    return resultado


def _ficha_kg(v):
    try:
        return f"{float(v or 0):,.0f} kg"
    except Exception:
        return f"{v} kg"


def _ficha_perfil_proveedor_historico(cur_lab, tarea):
    """Ficha determinÃ­stica: historia mensual de un proveedor + ranking actual."""
    proveedor = tarea["entidad"]
    periodo = tarea["periodo"]
    datos = {"proveedor": proveedor, "periodo": periodo}
    senales = {}

    cur_lab.execute(f"""
        SELECT meses_con_actividad, kg_promedio_meses_activos, kg_min_mes_activo,
               kg_max_mes_activo, pct_promedio_meses_activos, ultimo_mes_con_actividad,
               confiabilidad, historial_json, kg_actual, pct_actual_contexto
        FROM ia_biografia_protagonistas
        WHERE tipo_entidad = 'proveedor' AND entidad = %s
          AND periodo_actual = %s AND criterio_version = %s
        LIMIT 1
    """, (proveedor, periodo, DERIVADAS_VERSION))
    bio = cur_lab.fetchone()
    senales["tiene_biografia"] = bool(bio)

    if bio:
        try:
            historial = json.loads(bio["historial_json"] or "[]")
        except Exception:
            historial = []
        datos.update({
            "meses_con_actividad": int(bio["meses_con_actividad"] or 0),
            "kg_promedio_meses_activos": float(bio["kg_promedio_meses_activos"] or 0),
            "kg_min_mes_activo": float(bio["kg_min_mes_activo"] or 0),
            "kg_max_mes_activo": float(bio["kg_max_mes_activo"] or 0),
            "pct_promedio_meses_activos": float(bio["pct_promedio_meses_activos"] or 0),
            "ultimo_mes_con_actividad": bio["ultimo_mes_con_actividad"],
            "confiabilidad": bio["confiabilidad"],
            "historial_12m": historial[-12:],
            "kg_actual": float(bio["kg_actual"] or 0),
            "pct_actual_contexto": float(bio["pct_actual_contexto"] or 0),
        })
    else:
        # Fallback determinÃ­stico desde el resumen mensual de meses cerrados
        cur_lab.execute(f"""
            SELECT periodo, kilos_total AS kg, registros
            FROM ia_resumen_mensual_ingresos_proveedor
            WHERE Proveedor = %s AND estado_periodo = 'cerrado' AND criterio_version = %s
            ORDER BY periodo
        """, (proveedor, DERIVADAS_VERSION))
        hist = [
            {"periodo": h["periodo"], "kg": float(h["kg"] or 0), "registros": int(h["registros"] or 0)}
            for h in (cur_lab.fetchall() or [])
        ]
        kg_vals = [h["kg"] for h in hist]
        datos.update({
            "meses_con_actividad": len(hist),
            "kg_promedio_meses_activos": round(sum(kg_vals) / len(kg_vals), 2) if kg_vals else 0,
            "kg_min_mes_activo": round(min(kg_vals), 2) if kg_vals else 0,
            "kg_max_mes_activo": round(max(kg_vals), 2) if kg_vals else 0,
            "pct_promedio_meses_activos": None,
            "ultimo_mes_con_actividad": hist[-1]["periodo"] if hist else None,
            "confiabilidad": None,
            "historial_12m": hist[-12:],
        })

    # Ranking actual del proveedor entre protagonistas nivel 1 del periodo
    cur_lab.execute(f"""
        SELECT entidad, kg_entidad
        FROM ia_protagonistas_operativos
        WHERE nivel = 1 AND periodo = %s AND criterio_version = %s
        ORDER BY kg_entidad DESC, entidad
    """, (periodo, DERIVADAS_VERSION))
    ranking = cur_lab.fetchall() or []
    posicion = next((i + 1 for i, r in enumerate(ranking) if r["entidad"] == proveedor), None)
    datos["ranking_actual"] = (
        {"posicion": posicion, "total_protagonistas": len(ranking)} if posicion else None
    )
    senales["en_ranking_actual"] = posicion is not None
    senales["meses_con_actividad"] = datos["meses_con_actividad"]

    n = datos["meses_con_actividad"]
    resumen = (
        f"{proveedor}: {n} meses cerrados con actividad; "
        f"promedio {_ficha_kg(datos['kg_promedio_meses_activos'])}/mes "
        f"(min {_ficha_kg(datos['kg_min_mes_activo'])}, max {_ficha_kg(datos['kg_max_mes_activo'])})."
    ) if n else f"{proveedor}: sin meses cerrados con actividad registrada."
    if datos.get("pct_promedio_meses_activos"):
        resumen += f" ParticipaciÃ³n promedio {datos['pct_promedio_meses_activos']}% del contexto."
    if posicion:
        resumen += f" En {periodo} es #{posicion} de {len(ranking)} protagonistas de ingresos."
    else:
        resumen += f" Sin ranking de protagonistas en {periodo}."

    return {
        "titulo": f"Perfil histÃ³rico de proveedor: {proveedor}",
        "resumen": resumen,
        "datos": datos,
        "senales": senales,
    }


def _ficha_ranking_vecinos_proveedor_mes(cur_lab, tarea):
    """Ficha determinÃ­stica: posiciÃ³n del proveedor entre vecinos en un mes cerrado."""
    proveedor = tarea["entidad"]
    periodo = tarea["periodo"]

    cur_lab.execute(f"""
        SELECT Proveedor, kilos_total AS kg, registros
        FROM ia_resumen_mensual_ingresos_proveedor
        WHERE periodo = %s AND criterio_version = %s
        ORDER BY kilos_total DESC, Proveedor
    """, (periodo, DERIVADAS_VERSION))
    filas = cur_lab.fetchall() or []
    total_kg = sum(float(f["kg"] or 0) for f in filas)

    def _item(f):
        kg = float(f["kg"] or 0)
        return {
            "proveedor": f["Proveedor"],
            "kg": kg,
            "pct": round(kg / total_kg * 100, 2) if total_kg > 0 else 0,
        }

    idx = next((i for i, f in enumerate(filas) if f["Proveedor"] == proveedor), None)
    datos = {
        "proveedor": proveedor,
        "periodo": periodo,
        "total_proveedores": len(filas),
        "ranking_top": [_item(f) for f in filas[:10]],
        "posicion": (idx + 1) if idx is not None else None,
        "kg_mes": _item(filas[idx])["kg"] if idx is not None else 0,
        "pct_mes": _item(filas[idx])["pct"] if idx is not None else 0,
        "vecino_anterior": _item(filas[idx - 1]) if idx is not None and idx > 0 else None,
        "vecino_siguiente": _item(filas[idx + 1]) if idx is not None and idx + 1 < len(filas) else None,
    }
    senales = {
        "en_ranking": idx is not None,
        "es_lider_mes": idx == 0,
        "proveedores_mes": len(filas),
    }

    if idx is None:
        resumen = f"En {periodo}, {proveedor} no registrÃ³ ingresos (ranking de {len(filas)} proveedores sin Ã©l)."
    else:
        resumen = (
            f"En {periodo}, {proveedor} fue #{idx + 1} de {len(filas)} proveedores de ingresos "
            f"con {_ficha_kg(datos['kg_mes'])} ({datos['pct_mes']}% del mes)."
        )
        if datos["vecino_anterior"]:
            resumen += f" Arriba: {datos['vecino_anterior']['proveedor']} ({_ficha_kg(datos['vecino_anterior']['kg'])})."
        else:
            resumen += " Fue el lÃ­der del mes."
        if datos["vecino_siguiente"]:
            resumen += f" Abajo: {datos['vecino_siguiente']['proveedor']} ({_ficha_kg(datos['vecino_siguiente']['kg'])})."

    return {
        "titulo": f"Ranking de vecinos {periodo}: {proveedor}",
        "resumen": resumen,
        "datos": datos,
        "senales": senales,
    }


def _ficha_perfil_proveedor_material_historico(cur_op, cur_lab, tarea):
    """Ficha determinÃ­stica: material dentro de un proveedor, actual + historia."""
    material = tarea["entidad"]
    proveedor = tarea["entidad_2"]
    periodo = tarea["periodo"]
    fuente_material = tarea.get("material_fuente") or "Description"
    es_normalizado = fuente_material == "DescriptionNormalizada"
    datos = {"proveedor": proveedor, "material": material, "periodo": periodo,
             "material_fuente": fuente_material}
    senales = {"material_normalizado": es_normalizado}

    cur_lab.execute(f"""
        SELECT kg_actual, pct_actual_contexto, meses_con_actividad,
               confiabilidad, historial_json, ultimo_mes_con_actividad
        FROM ia_biografia_protagonistas
        WHERE tipo_entidad = 'proveedor_material' AND entidad = %s AND entidad_2 = %s
          AND periodo_actual = %s AND criterio_version = %s
        LIMIT 1
    """, (material, proveedor, periodo, DERIVADAS_VERSION))
    bio = cur_lab.fetchone()
    senales["tiene_biografia"] = bool(bio)

    if bio:
        try:
            historial = json.loads(bio["historial_json"] or "[]")
        except Exception:
            historial = []
        datos.update({
            "kg_actual": float(bio["kg_actual"] or 0),
            "pct_dentro_proveedor": float(bio["pct_actual_contexto"] or 0),
            "meses_con_actividad": int(bio["meses_con_actividad"] or 0),
            "confiabilidad": bio["confiabilidad"],
            "ultimo_mes_con_actividad": bio["ultimo_mes_con_actividad"],
            "historial_12m": historial[-12:],
        })
    else:
        # Fallback: historia en meses cerrados desde la base operativa
        # (incluye variantes crudas del proveedor canÃ³nico por alias; la
        # condiciÃ³n de material respeta la fuente de la tarea, sin mezclar)
        _mapa_f, inverso_f = cargar_alias_proveedores(cur_lab)
        variantes_f = variantes_proveedor(proveedor, inverso_f)
        marcadores_f = ", ".join(["%s"] * len(variantes_f))
        if fuente_material == "DescriptionNormalizada":
            cond_mat_f = "DescriptionNormalizada = %s"
            params_mat_f = [material]
        else:
            cond_mat_f = "(Description = %s OR Materiales = %s)"
            params_mat_f = [material, material]
        cur_op.execute(f"""
            SELECT DATE_FORMAT(FechaHora, '%%Y-%%m') AS periodo,
                   COUNT(*) AS registros,
                   COALESCE(SUM(kilos), 0) AS kg
            FROM TiposDeMovimiento
            WHERE {_sql_tipo_compra_proveedor()}
              AND Proveedor IN ({marcadores_f})
              AND {cond_mat_f}
              AND DATE_FORMAT(FechaHora, '%%Y-%%m') < %s
            GROUP BY periodo
            ORDER BY periodo
        """, tuple(variantes_f + params_mat_f + [periodo]))
        hist = [
            {"periodo": h["periodo"], "kg": float(h["kg"] or 0), "registros": int(h["registros"] or 0)}
            for h in (cur_op.fetchall() or [])
        ]
        cur_lab.execute(f"""
            SELECT kg_entidad, pct_del_contexto
            FROM ia_protagonistas_operativos
            WHERE nivel = 2 AND entidad = %s AND entidad_2 = %s
              AND periodo = %s AND criterio_version = %s
            LIMIT 1
        """, (material, proveedor, periodo, DERIVADAS_VERSION))
        prot = cur_lab.fetchone() or {}
        datos.update({
            "kg_actual": float(prot.get("kg_entidad") or 0),
            "pct_dentro_proveedor": float(prot.get("pct_del_contexto") or 0),
            "meses_con_actividad": len(hist),
            "confiabilidad": None,
            "ultimo_mes_con_actividad": hist[-1]["periodo"] if hist else None,
            "historial_12m": hist[-12:],
        })

    senales["meses_con_actividad"] = datos["meses_con_actividad"]
    n = datos["meses_con_actividad"]
    etiqueta_mat = "material normalizado" if es_normalizado else "material"
    resumen = (
        f"{material} ({etiqueta_mat}) de {proveedor}: {_ficha_kg(datos['kg_actual'])} en {periodo} "
        f"({datos['pct_dentro_proveedor']}% de los kilos del proveedor); "
    )
    resumen += (
        f"activo {n} meses cerrados previos (Ãºltimo: {datos['ultimo_mes_con_actividad']})."
        if n else "sin meses cerrados previos con este material."
    )

    return {
        "titulo": (f"Perfil histÃ³rico proveedor+material normalizado: {proveedor} â†’ {material}"
                   if es_normalizado else
                   f"Perfil histÃ³rico proveedor+material: {proveedor} â†’ {material}"),
        "resumen": resumen,
        "datos": datos,
        "senales": senales,
    }


def _ficha_perfil_material_global(cur_op, tarea, mapa_alias=None):
    """Ficha determinÃ­stica: material a nivel global (todos los proveedores, meses cerrados).
    mapa_alias canoniza los proveedores antes de agrupar/rankear. La condiciÃ³n de
    material respeta material_fuente de la tarea (crudo o normalizado, sin mezclar)."""
    material = tarea["entidad"]
    periodo = tarea["periodo"]
    fuente_material = tarea.get("material_fuente") or "Description"
    es_normalizado = fuente_material == "DescriptionNormalizada"
    if es_normalizado:
        cond_mat_g = "DescriptionNormalizada = %s"
        params_mat_g = [material]
    else:
        cond_mat_g = "(Description = %s OR Materiales = %s)"
        params_mat_g = [material, material]
    inicio_periodo = f"{periodo}-01"  # meses cerrados = anteriores al periodo de la tarea

    cur_op.execute(f"""
        SELECT Proveedor,
               COUNT(*) AS registros,
               COALESCE(SUM(kilos), 0) AS kg
        FROM TiposDeMovimiento
        WHERE {_sql_tipo_compra_proveedor()}
          AND {cond_mat_g}
          AND FechaHora < %s
          AND Proveedor IS NOT NULL AND TRIM(Proveedor) <> ''
        GROUP BY Proveedor
        ORDER BY kg DESC
    """, tuple(params_mat_g + [inicio_periodo]))
    _agr_mat = {}
    for p in (cur_op.fetchall() or []):
        canon = canonizar_proveedor(p["Proveedor"], mapa_alias)
        acc = _agr_mat.setdefault(canon, {"proveedor": canon, "kg": 0.0, "registros": 0})
        acc["kg"] += float(p["kg"] or 0)
        acc["registros"] += int(p["registros"] or 0)
    provs = sorted(_agr_mat.values(), key=lambda x: -x["kg"])
    kg_total = sum(p["kg"] for p in provs)

    cur_op.execute(f"""
        SELECT DATE_FORMAT(FechaHora, '%%Y-%%m') AS periodo,
               COUNT(*) AS registros,
               COALESCE(SUM(kilos), 0) AS kg
        FROM TiposDeMovimiento
        WHERE {_sql_tipo_compra_proveedor()}
          AND {cond_mat_g}
          AND FechaHora < %s
        GROUP BY periodo
        ORDER BY periodo DESC
        LIMIT 12
    """, tuple(params_mat_g + [inicio_periodo]))
    kg_por_mes = [
        {"periodo": h["periodo"], "kg": float(h["kg"] or 0), "registros": int(h["registros"] or 0)}
        for h in reversed(cur_op.fetchall() or [])
    ]

    dominante = provs[0] if provs else None
    pct_dominante = round(dominante["kg"] / kg_total * 100, 2) if dominante and kg_total > 0 else 0
    datos = {
        "material": material,
        "material_fuente": fuente_material,
        "periodo": periodo,
        "proveedores_historicos": provs[:10],
        "proveedores_distintos": len(provs),
        "kg_total_historico": round(kg_total, 2),
        "kg_por_mes_12m": kg_por_mes,
        "proveedor_dominante": ({**dominante, "pct": pct_dominante} if dominante else None),
    }
    senales = {
        "proveedores_distintos": len(provs),
        "monoproveedor": len(provs) == 1,
        "dominante_concentra_mas_50pct": pct_dominante > 50,
        "material_normalizado": es_normalizado,
    }

    etiqueta_mat = "material normalizado" if es_normalizado else "material"
    if not provs:
        resumen = f"{material} ({etiqueta_mat}): sin ingresos registrados en meses cerrados."
    else:
        kg_12m = sum(h["kg"] for h in kg_por_mes)
        resumen = (
            f"{material} ({etiqueta_mat}): traÃ­do histÃ³ricamente por {len(provs)} proveedores; "
            f"dominante {dominante['proveedor']} ({pct_dominante}% del kg histÃ³rico). "
            f"Ãšltimos {len(kg_por_mes)} meses cerrados: {_ficha_kg(kg_12m)}."
        )

    return {
        "titulo": (f"Perfil global de material normalizado: {material}"
                   if es_normalizado else f"Perfil global de material: {material}"),
        "resumen": resumen,
        "datos": datos,
        "senales": senales,
    }


def _ficha_material_normalizado_historico(cur_lab, tarea):
    """Ficha determinÃ­stica: historia mensual de un material normalizado comprable."""
    material = tarea["entidad"]
    periodo = tarea["periodo"]
    cur_lab.execute(f"""
        SELECT periodo, SUM(kilos_total) AS kg, SUM(registros) AS registros,
               SUM(COALESCE(monto_estimado, 0)) AS monto
        FROM ia_resumen_mensual_material_normalizado_tipo
        WHERE material_normalizado = %s AND criterio_version = %s
          AND {_sql_tipo_compra_proveedor('tipo_movimiento')}
        GROUP BY periodo
        ORDER BY periodo
    """, (material, DERIVADAS_VERSION))
    hist = [{"periodo": r["periodo"], "kg": float(r["kg"] or 0),
             "registros": int(r["registros"] or 0), "monto": float(r["monto"] or 0)}
            for r in (cur_lab.fetchall() or [])]
    actual = next((h for h in hist if h["periodo"] == periodo), None)
    previos = [h for h in hist if h["periodo"] < periodo]
    kg_actual = actual["kg"] if actual else 0
    kg_prom = round(sum(h["kg"] for h in previos) / len(previos), 2) if previos else 0
    datos = {
        "material": material, "material_fuente": "DescriptionNormalizada", "periodo": periodo,
        "kg_actual": kg_actual, "meses_previos": len(previos),
        "kg_promedio_meses_previos": kg_prom, "historial_12m": hist[-12:],
    }
    senales = {"material_normalizado": True, "sin_historial_previo": not previos}
    resumen = f"{material} (material normalizado): {_ficha_kg(kg_actual)} comprados en {periodo}; "
    resumen += (f"historial {len(previos)} meses previos; promedio {_ficha_kg(kg_prom)}/mes."
                if previos else "sin historial normalizado previo.")
    return {"titulo": f"Perfil histÃ³rico de material normalizado: {material}",
            "resumen": resumen, "datos": datos, "senales": senales}


def _ficha_proveedor_material_normalizado_historico(cur_lab, tarea):
    """Ficha determinÃ­stica: compras de un proveedor para un material normalizado."""
    material = tarea["entidad"]
    proveedor = tarea["entidad_2"]
    periodo = tarea["periodo"]
