def _compactar_relaciones_export(items, limite=50):
    """VersiÃ³n liviana de relaciones para el snapshot: sin evidencia cruda."""
    compactas = []
    for r in (items or [])[:limite]:
        if isinstance(r, dict):
            compactas.append({k: v for k, v in r.items()
                              if k not in ("evidencia", "evidencia_json", "salida_json")})
        else:
            compactas.append(r)
    return compactas




def _normalizar_payload_plan_compras(payload):
    if not isinstance(payload, dict):
        return {}, {}
    data = payload.get('data') if isinstance(payload.get('data'), dict) else payload
    tablero = data.get('tablero') if isinstance(data.get('tablero'), dict) else payload.get('tablero') if isinstance(payload.get('tablero'), dict) else None
    if isinstance(tablero, dict):
        return tablero, data
    return data if isinstance(data, dict) else {}, data if isinstance(data, dict) else {}


def _score_payload_plan_compras(payload):
    data, raw = _normalizar_payload_plan_compras(payload)
    candidates = [x for x in (data, raw, payload) if isinstance(x, dict)]
    plan = data.get('plan') if isinstance(data.get('plan'), list) else []
    tareas = data.get('tareas') if isinstance(data.get('tareas'), list) else []
    mix = data.get('mixMensual') if isinstance(data.get('mixMensual'), dict) else {}
    modelo = data.get('modeloCompras') if isinstance(data.get('modeloCompras'), dict) else {}
    score = len(plan) * 10 + len(tareas)
    if mix: score += 20
    if modelo: score += 10
    for c in candidates:
        decision = c.get('decision') if isinstance(c.get('decision'), dict) else {}
        if decision.get('tareasCompras'): score += 120
        if decision.get('planMensual'): score += 90
        if decision.get('comprarRamas'): score += 40
        if isinstance(c.get('tareasCompras'), list): score += 100
        if isinstance(c.get('filas'), list): score += 60
        if isinstance(c.get('guiaDecision'), dict): score += 25
        if c.get('meta'): score += 5
    return score

def extraer_plan_y_mix_compras_vigente():
    """Devuelve la parte humana/operativa del plan recibido y tomado como verdad."""

    def _payload_fuente_o_ingesta(clave_fuente, tipo_ingesta):
        item = por_clave.get(clave_fuente)
        payload_item = item.get('payload') if item and isinstance(item.get('payload'), dict) else {}
        data_item = payload_item.get('data') if isinstance(payload_item.get('data'), dict) else payload_item
        if isinstance(data_item, dict) and data_item:
            return data_item
        conn_tmp = get_ia_connection()
        if not conn_tmp:
            return {}
        try:
            cur_tmp = conn_tmp.cursor()
            ensure_mqtt_tables(cur_tmp)
            cur_tmp.execute("""
                SELECT payload_json
                FROM ia_mqtt_ingesta
                WHERE tipo_detectado = %s
                  AND payload_json IS NOT NULL
                  AND CHAR_LENGTH(payload_json) > 20
                ORDER BY recibido_en DESC, id DESC
                LIMIT 30
            """, (tipo_ingesta,))
            for rr in (cur_tmp.fetchall() or []):
                try:
                    pj = json.loads(rr.get('payload_json') or '{}')
                except Exception:
                    continue
                if not isinstance(pj, dict) or not pj:
                    continue
                data_pj = pj.get('data') if isinstance(pj.get('data'), dict) else pj
                if isinstance(data_pj, dict) and data_pj and not set(data_pj.keys()).issubset({'tipo','origen','topic','archivo','generadoEn','hash','data'}):
                    cur_tmp.close(); conn_tmp.close()
                    return data_pj
            cur_tmp.close(); conn_tmp.close()
        except Exception:
            try:
                conn_tmp.close()
            except Exception:
                pass
        return {}

    fuentes = _leer_fuentes_operativas_vigentes(include_payload=True, limite=30)
    if not fuentes.get('ok'):
        return {"ok": False, "error": fuentes.get('error'), "fuentes_disponibles": []}
    items = fuentes.get('items') or []
    por_clave = {}
    for x in items:
        clave = x.get('clave')
        if clave and clave not in por_clave:
            por_clave[clave] = x

    criterios = [x for x in items if x.get('clave') == 'plan_compras_criterio']
    criterio = None
    if criterios:
        criterio = sorted(criterios, key=lambda x: (_score_payload_plan_compras(x.get('payload')), str(x.get('actualizado_en') or '')), reverse=True)[0]
    if not criterio:
        return {
            "ok": False,
            "error": "sin_plan_compras_criterio_vigente",
            "fuentes_disponibles": sorted([k for k in por_clave.keys() if k]),
        }

    payload = criterio.get('payload') if isinstance(criterio.get('payload'), dict) else {}
    data, data_original = _normalizar_payload_plan_compras(payload)

    def fuente_resumen(x):
        if not x:
            return None
        return {
            "clave": x.get('clave'),
            "periodo": x.get('periodo'),
            "fuente": x.get('fuente'),
            "topic": x.get('topic'),
            "titulo": x.get('titulo'),
            "resumen": x.get('resumen'),
            "actualizado_en": x.get('actualizado_en'),
            "hash_sha256": x.get('hash_sha256'),
            "preview": x.get('preview') or {},
        }

    def fuente_payload(clave):
        x = por_clave.get(clave)
        if not x:
            return {}
        payload_x = x.get('payload') if isinstance(x.get('payload'), dict) else {}
        data_x, raw_x = _normalizar_payload_plan_compras(payload_x)
        if data_x:
            return data_x
        if isinstance(raw_x, dict) and raw_x:
            return raw_x
        return payload_x if payload_x else {}

    plan = data.get('plan') if isinstance(data.get('plan'), list) else []
    tareas = data.get('tareas') if isinstance(data.get('tareas'), list) else []
    mix = data.get('mixMensual') if isinstance(data.get('mixMensual'), dict) else {}
    modelo = data.get('modeloCompras') if isinstance(data.get('modeloCompras'), dict) else {}
    meta = data.get('meta') if isinstance(data.get('meta'), dict) else {}
    raw = data_original if isinstance(data_original, dict) else {}
    raw_data = raw.get('data') if isinstance(raw.get('data'), dict) else {}
    fuentes_rich = [x for x in (data, raw, raw_data, payload) if isinstance(x, dict)]

    def _primer_dict_fuente(nombre):
        for src in fuentes_rich:
            v = src.get(nombre)
            if isinstance(v, dict):
                return v
        return {}

    def _primer_lista_fuente(nombre):
        for src in fuentes_rich:
            v = src.get(nombre)
            if isinstance(v, list):
                return v
        return []

    decision = _primer_dict_fuente('decision')
    filas_detalle = _primer_lista_fuente('filas')
    guia = _primer_dict_fuente('guiaDecision')
    tareas_compras = _primer_lista_fuente('tareasCompras') or (decision.get('tareasCompras') if isinstance(decision.get('tareasCompras'), list) else [])
    if not tareas and tareas_compras:
        tareas = tareas_compras
    periodo = data.get('mesKey') or meta.get('mesKey') or criterio.get('periodo') or payload.get('mesKey') or data_original.get('mesKey') or raw.get('mesKey')
    objetivo_total = (mix.get('objetivoTotalTn') or data.get('objetivoTotalTn') or
                      meta.get('objetivoTotalTn') or meta.get('objetivoTotalKg'))

    return {
        "ok": True,
        "lectura": "Plan/mix de compras recibido por HTTP/MQTT y tomado como criterio humano vigente.",
        "periodo": periodo,
        "fuente_criterio": fuente_resumen(criterio),
        "mixMensual": mix,
        "modeloCompras": modelo,
        "decision": decision,
        "filas_detalle": filas_detalle[:80],
        "guiaDecision": guia,
        "arbol": _primer_lista_fuente('arbol'),
        "planos": _primer_dict_fuente('planos'),
        "realesAuditoria": _primer_dict_fuente('realesAuditoria'),
        "stockAuditoria": _primer_dict_fuente('stockAuditoria'),
        "plan": plan,
        "tareas": tareas[:30],
        "tareasCompras": tareas_compras[:40],
        "resumen_numerico": {
            "ramas_plan": len(plan),
            "tareas": len(tareas),
            "objetivoTotalTn": objetivo_total,
            "formato_detectado": "tablero_envuelto" if isinstance(data_original.get('tablero'), dict) else "json_directo",
        },
        "fuentes_relacionadas": {
            "stock": fuente_resumen(por_clave.get('plan_compras_stock')),
            "agenda": fuente_resumen(por_clave.get('plan_compras_agenda')),
            "compras_reales_externas": fuente_resumen(por_clave.get('plan_compras_reales')),
        },
        "fuentes_payload": {
            "stock": fuente_payload('plan_compras_stock') or _payload_fuente_o_ingesta('plan_compras_stock', 'stock_snapshot'),
            "agenda": fuente_payload('plan_compras_agenda') or _payload_fuente_o_ingesta('plan_compras_agenda', 'agenda_compras'),
            "compras_reales_externas": fuente_payload('plan_compras_reales'),
            "compras_mes_v4": fuente_payload('compras_mes_v4') or _payload_fuente_o_ingesta('compras_mes_v4', 'compras_mes_v4'),
        },
        "contrato": {
            "autoridad": "Este plan/mix se considera verdad operativa humana hasta que llegue una version mas nueva por HTTP/MQTT.",
            "uso": "Comparar contra compras reales MySQL, stock vigente y agenda para decidir prioridades de compra.",
        }
    }

